package auth

import "github.com/gin-gonic/gin"

// RegisterPublicRoutes 注册无需登录的鉴权路由。
func (m *Module) RegisterPublicRoutes(api *gin.RouterGroup) {
	api.GET("/auth/login-options", m.Handler.LoginOptions)
	api.POST("/auth/login", m.Handler.Login)
	api.POST("/auth/2fa/email/start", m.Handler.StartTwoFactorEmailVerification)
	api.POST("/auth/2fa/verify", m.Handler.VerifyTwoFactorLogin)
	api.POST("/auth/register/email/start", m.Handler.StartEmailRegistration)
	api.POST("/auth/register/email/complete", m.Handler.CompleteEmailRegistration)
	api.POST("/auth/password/reset/start", m.Handler.StartPasswordReset)
	api.POST("/auth/password/reset/complete", m.Handler.CompletePasswordReset)
	api.POST("/auth/refresh", m.Handler.RefreshToken)
	api.GET("/auth/providers/:slug/start", m.Handler.StartProviderLogin)
	api.POST("/auth/providers/:slug/authorize", m.Handler.StartProviderAuthBridge)
	api.GET("/auth/providers/:slug/callback", m.Handler.ProviderCallback)
	api.POST("/auth/providers/:slug/callback", m.Handler.CompleteProviderLogin)
	api.POST("/auth/providers/:slug/exchange", m.Handler.ExchangeProviderAuthBridgeGrant)
}

// RegisterProtectedRoutes 注册需登录的鉴权路由。
func (m *Module) RegisterProtectedRoutes(authRequired *gin.RouterGroup) {
	authRequired.GET("/me", m.Handler.Me)
	authRequired.PATCH("/me", m.Handler.PatchMe)
	authRequired.PATCH("/me/username", m.Handler.PatchUsername)
	authRequired.POST("/me/onboarding/complete", m.Handler.CompleteOnboarding)
	authRequired.POST("/me/delete/start", m.Handler.StartAccountDeleteVerification)
	authRequired.DELETE("/me", m.Handler.DeleteMe)
	authRequired.POST("/auth/password/change/start", m.Handler.StartPasswordChangeVerification)
	authRequired.POST("/auth/password/change/complete", m.Handler.ChangePassword)
	authRequired.POST("/me/email/bootstrap/start", m.Handler.StartEmailBootstrap)
	authRequired.POST("/me/email/bootstrap/complete", m.Handler.CompleteEmailBootstrap)
	authRequired.POST("/me/email/verify-current/start", m.Handler.StartCurrentEmailVerification)
	authRequired.POST("/me/email/verify-current/complete", m.Handler.CompleteCurrentEmailVerification)
	authRequired.POST("/me/email/change/start-current", m.Handler.StartCurrentEmailChange)
	authRequired.POST("/me/email/change/start-new", m.Handler.StartNewEmailChange)
	authRequired.POST("/me/email/change/complete", m.Handler.CompleteEmailChange)
	authRequired.GET("/me/2fa", m.Handler.CurrentTwoFactorStatus)
	authRequired.POST("/me/2fa/setup/start", m.Handler.StartCurrentTwoFactorSetup)
	authRequired.POST("/me/2fa/setup/confirm", m.Handler.ConfirmCurrentTwoFactorSetup)
	authRequired.DELETE("/me/2fa/setup", m.Handler.CancelCurrentTwoFactorSetup)
	authRequired.POST("/me/2fa/recovery/regenerate", m.Handler.RegenerateCurrentTwoFactorRecoveryCodes)
	authRequired.POST("/me/2fa/disable", m.Handler.DisableCurrentTwoFactor)
	authRequired.GET("/me/identities", m.Handler.ListCurrentUserIdentities)
	authRequired.POST("/me/identities/providers/:slug/callback", m.Handler.CompleteProviderBind)
	authRequired.DELETE("/me/identities/:identity_id", m.Handler.DeleteCurrentUserIdentity)
	authRequired.GET("/auth/sessions", m.Handler.CurrentSessions)
	authRequired.PUT("/auth/sessions/current/location", m.Handler.UpdateCurrentSessionLocation)
	authRequired.POST("/auth/sessions/:session_id/logout", m.Handler.LogoutSession)
	authRequired.POST("/auth/logout", m.Handler.Logout)
	authRequired.POST("/auth/logout-all", m.Handler.LogoutAll)
}

func (m *Module) RegisterAdminRoutes(adminGroup *gin.RouterGroup) {
	adminGroup.GET("/auth/providers", m.Handler.ListIdentityProviders)
	adminGroup.POST("/auth/providers", m.Handler.CreateIdentityProvider)
	adminGroup.PATCH("/auth/provider-order", m.Handler.ReorderIdentityProviders)
	adminGroup.PATCH("/auth/providers/:provider_id", m.Handler.UpdateIdentityProvider)
	adminGroup.DELETE("/auth/providers/:provider_id", m.Handler.DeleteIdentityProvider)
}

package auth

import (
	"errors"
	"io"
	"net/http"
	"strconv"
	"strings"
	"time"

	appauth "github.com/DEEIX-AI/DEEIX-Chat/backend/internal/application/auth"
	"github.com/DEEIX-AI/DEEIX-Chat/backend/internal/application/user"
	"github.com/DEEIX-AI/DEEIX-Chat/backend/internal/shared/response"
	"github.com/DEEIX-AI/DEEIX-Chat/backend/internal/transport/http/middleware"
	"github.com/gin-gonic/gin"
)

const refreshTokenCookieName = "deeix_chat_refresh_token"

// Handler 封装认证 HTTP 处理。
type Handler struct {
	service *appauth.Service
}

// NewHandler 创建处理器。
func NewHandler(service *appauth.Service) *Handler {
	return &Handler{
		service: service,
	}
}

func (h *Handler) recordAudit(c *gin.Context, userID uint, action string, resource string, resourceID string, detail interface{}) {
	h.service.RecordAudit(c.Request.Context(), appauth.AuditInput{
		UserID:     userID,
		RequestID:  middleware.MustRequestID(c),
		Action:     action,
		Resource:   resource,
		ResourceID: resourceID,
		ClientIP:   c.ClientIP(),
		UserAgent:  c.Request.UserAgent(),
		Detail:     detail,
	})
}

func bindOptionalJSON(c *gin.Context, req interface{}) error {
	if c.Request.Body == nil || c.Request.ContentLength == 0 {
		return nil
	}
	if err := c.ShouldBindJSON(req); err != nil && !errors.Is(err, io.EOF) {
		return err
	}
	return nil
}

func (h *Handler) writeRefreshTokenCookie(c *gin.Context, result *appauth.LoginResult) {
	if result == nil || result.RefreshToken == "" || result.RefreshExpiresAt.IsZero() {
		return
	}
	maxAge := int(time.Until(result.RefreshExpiresAt).Seconds())
	if maxAge < 0 {
		maxAge = 0
	}
	http.SetCookie(c.Writer, &http.Cookie{
		Name:     refreshTokenCookieName,
		Value:    result.RefreshToken,
		Path:     "/api/v1/auth",
		Expires:  result.RefreshExpiresAt,
		MaxAge:   maxAge,
		HttpOnly: true,
		Secure:   h.shouldUseSecureCookie(c),
		SameSite: http.SameSiteLaxMode,
	})
}

func (h *Handler) clearRefreshTokenCookie(c *gin.Context) {
	http.SetCookie(c.Writer, &http.Cookie{
		Name:     refreshTokenCookieName,
		Value:    "",
		Path:     "/api/v1/auth",
		Expires:  time.Unix(0, 0),
		MaxAge:   -1,
		HttpOnly: true,
		Secure:   h.shouldUseSecureCookie(c),
		SameSite: http.SameSiteLaxMode,
	})
}

func isHTTPSRequest(c *gin.Context) bool {
	if c.Request.TLS != nil {
		return true
	}
	return c.GetHeader("X-Forwarded-Proto") == "https"
}

func (h *Handler) shouldUseSecureCookie(c *gin.Context) bool {
	return isHTTPSRequest(c) || (h.service != nil && h.service.ShouldUseSecureCookies())
}

// LoginOptions godoc
// @Summary 获取登录入口配置
// @Description 获取用户名、邮箱、OAuth/OIDC 登录入口，以及邮箱注册 Turnstile 公共配置
// @Tags auth
// @Produce json
// @Success 200 {object} LoginOptionsResponseDoc
// @Failure 500 {object} ErrorDoc
// @Router /auth/login-options [get]
func (h *Handler) LoginOptions(c *gin.Context) {
	result, err := h.service.GetLoginOptions(c.Request.Context())
	if err != nil {
		response.Error(c, http.StatusInternalServerError, "get login options failed")
		return
	}
	response.Success(c, toLoginOptionsResponse(result))
}

// StartEmailRegistration godoc
// @Summary 发送邮箱注册验证码
// @Description 邮箱验证码注册开启时发送验证码；启用 Turnstile 后需要提交 turnstileToken
// @Tags auth
// @Accept json
// @Produce json
// @Param body body EmailRegistrationStartRequest true "邮箱注册验证码请求"
// @Success 200 {object} EmailRegistrationStartResponseDoc
// @Failure 400 {object} ErrorDoc
// @Router /auth/register/email/start [post]
func (h *Handler) StartEmailRegistration(c *gin.Context) {
	var req EmailRegistrationStartRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		response.InvalidRequestBody(c, err)
		return
	}
	result, err := h.service.RequestEmailRegistration(
		c.Request.Context(),
		req.Email,
		req.TurnstileToken,
		c.ClientIP(),
		middleware.MustRequestID(c),
		middleware.ResolveSessionAuditContext(c),
	)
	if err != nil {
		response.ErrorFrom(c, http.StatusBadRequest, err)
		return
	}
	response.Success(c, toEmailRegistrationStartResponse(result))
}

// CompleteEmailRegistration godoc
// @Summary 完成邮箱注册
// @Description 使用邮箱、密码和验证码完成注册；未开启邮箱验证码但启用 Turnstile 时需要提交 turnstileToken
// @Tags auth
// @Accept json
// @Produce json
// @Param body body EmailRegistrationCompleteRequest true "邮箱注册完成请求"
// @Success 200 {object} LoginResponseDoc
// @Failure 400 {object} ErrorDoc
// @Router /auth/register/email/complete [post]
func (h *Handler) CompleteEmailRegistration(c *gin.Context) {
	var req EmailRegistrationCompleteRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		response.InvalidRequestBody(c, err)
		return
	}
	result, err := h.service.RegisterWithEmail(
		c.Request.Context(),
		req.Email,
		req.Password,
		req.Code,
		req.TurnstileToken,
		c.ClientIP(),
		middleware.MustRequestID(c),
		middleware.ResolveSessionAuditContext(c),
	)
	if err != nil {
		response.ErrorFrom(c, http.StatusBadRequest, err)
		return
	}
	h.writeRefreshTokenCookie(c, result)
	response.Success(c, toLoginResponse(result))
}

// StartPasswordReset godoc
// @Summary 发送密码重置验证码
// @Description SMTP 配置可用时，向已验证邮箱发送密码重置验证码；失败时返回通用错误，避免暴露账号状态
// @Tags auth
// @Accept json
// @Produce json
// @Param body body PasswordResetStartRequest true "密码重置验证码请求"
// @Success 200 {object} PasswordResetStartResponseDoc
// @Failure 400 {object} ErrorDoc
// @Failure 429 {object} ErrorDoc
// @Router /auth/password/reset/start [post]
func (h *Handler) StartPasswordReset(c *gin.Context) {
	var req PasswordResetStartRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		response.InvalidRequestBody(c, err)
		return
	}
	result, err := h.service.RequestPasswordReset(
		c.Request.Context(),
		req.Email,
		middleware.MustRequestID(c),
		middleware.ResolveSessionAuditContext(c),
	)
	if err != nil {
		if errors.Is(err, appauth.ErrPasswordResetFailed) {
			response.Error(c, http.StatusBadRequest, "password reset failed")
			return
		}
		response.Error(c, http.StatusInternalServerError, "password reset failed")
		return
	}
	response.Success(c, toPasswordResetStartResponse(result))
}

// CompletePasswordReset godoc
// @Summary 完成密码重置
// @Description 使用邮箱、验证码和新密码完成密码重置；失败时返回通用错误，避免暴露账号状态
// @Tags auth
// @Accept json
// @Produce json
// @Param body body PasswordResetCompleteRequest true "密码重置完成请求"
// @Success 200 {object} PasswordResetCompleteResponseDoc
// @Failure 400 {object} ErrorDoc
// @Failure 429 {object} ErrorDoc
// @Router /auth/password/reset/complete [post]
func (h *Handler) CompletePasswordReset(c *gin.Context) {
	var req PasswordResetCompleteRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		response.InvalidRequestBody(c, err)
		return
	}
	if err := h.service.CompletePasswordReset(
		c.Request.Context(),
		req.Email,
		req.Code,
		req.NewPassword,
		middleware.MustRequestID(c),
		middleware.ResolveSessionAuditContext(c),
	); err != nil {
		if errors.Is(err, appauth.ErrPasswordResetFailed) {
			response.Error(c, http.StatusBadRequest, "password reset failed")
			return
		}
		response.ErrorFrom(c, http.StatusBadRequest, err)
