	}
	auditCtx := middleware.ResolveSessionAuditContext(c)
	result, err := h.service.VerifyLoginTwoFactor(
		c.Request.Context(),
		req.ChallengeToken,
		req.VerificationMethod,
		req.Code,
		middleware.MustRequestID(c),
