		return
	}

	var req PatchUsernameRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		response.InvalidRequestBody(c, err)
		return
	}

	item, err := h.service.UpdateUsernameOnce(c.Request.Context(), userID, toUpdateUsernameInput(req))
	if err != nil {
