}

// Snapshot 返回当前配置快照。
func (r *Runtime) Snapshot() Config {
	if r == nil {
		return Config{}
	}
	value := r.value.Load()
	if value == nil {
		return Config{}
	}
	item, ok := value.(Config)
	if !ok {
		return Config{}
	}
	return item
}

