package registrationcode

import (
	"context"
	"crypto/rand"
	"fmt"
	"strings"
	"time"

	domainregistrationcode "github.com/DEEIX-AI/DEEIX-Chat/backend/internal/domain/registrationcode"
	"github.com/DEEIX-AI/DEEIX-Chat/backend/internal/repository"
)

const (
	defaultQuantity = 1
	maxQuantity = 100
	codeLength = 16
	reservationTTL = 10 * time.Minute
)

type Service struct { repo repository.RegistrationCodeRepository }

func NewService(repo repository.RegistrationCodeRepository) *Service { return &Service{repo: repo} }

type CodeView struct { domainregistrationcode.RegistrationCode }

func (s *Service) Create(ctx context.Context, actorUserID uint, quantity int) ([]CodeView, error) {
	if quantity == 0 { quantity = defaultQuantity }
	if actorUserID == 0 || quantity < 1 || quantity > maxQuantity { return nil, repository.ErrInvalidInput }
	result := make([]CodeView, 0, quantity)
	for i := 0; i < quantity; i++ {
		for attempt := 0; attempt < 5; attempt++ {
			code, err := generateCode()
			if err != nil { return nil, err }
			item := &domainregistrationcode.RegistrationCode{Code: code, CodeHint: code[len(code)-4:], Status: domainregistrationcode.StatusActive, CreatedByUserID: actorUserID}
			if err = s.repo.Create(ctx, item); err != nil {
				if err == repository.ErrDuplicate { continue }
				return nil, err
			}
			result = append(result, CodeView{RegistrationCode: *item})
			break
		}
	}
	return result, nil
}

func (s *Service) List(ctx context.Context, page, pageSize int, status string) ([]CodeView, int64, error) {
	if page < 1 { page = 1 }; if pageSize < 1 { pageSize = 20 }; if pageSize > 100 { pageSize = 100 }
	items, total, err := s.repo.List(ctx, repository.RegistrationCodeListFilter{Status: status}, (page-1)*pageSize, pageSize)
	if err != nil { return nil, 0, err }
	result := make([]CodeView, 0, len(items)); for _, item := range items { result = append(result, CodeView{RegistrationCode: item}) }
	return result, total, nil
}

func (s *Service) Disable(ctx context.Context, id uint) error { return s.repo.Disable(ctx, id) }
func (s *Service) Delete(ctx context.Context, id uint) error { return s.repo.DeleteUnused(ctx, id) }

func (s *Service) Reserve(ctx context.Context, code string) (*domainregistrationcode.RegistrationCode, error) {
	return s.repo.Reserve(ctx, strings.TrimSpace(code), time.Now(), time.Now().Add(reservationTTL))
}
func (s *Service) Commit(ctx context.Context, id, userID uint) error { return s.repo.Commit(ctx, id, userID, time.Now()) }
func (s *Service) Release(ctx context.Context, id uint) error { return s.repo.Release(ctx, id) }

func generateCode() (string, error) {
	const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
	buf := make([]byte, codeLength)
	raw := make([]byte, codeLength)
	if _, err := rand.Read(raw); err != nil { return "", err }
	for i := range buf { buf[i] = alphabet[int(raw[i])%len(alphabet)] }
	return fmt.Sprintf("%s-%s-%s-%s", string(buf[:4]), string(buf[4:8]), string(buf[8:12]), string(buf[12:])), nil
}

