		}
	}
	authURL, _, _, err := s.resolveProviderEndpoints(ctx, *provider)
	if err != nil {
		return "", err
	}
	state, err := s.signProviderState(providerOAuthState{
		Provider:      slug,
		RedirectURI:   redirectURI,
		Next:          normalizeProviderNextPath(nextPath),
		Intent:        normalizedIntent,
