package registrationcode

import (
	"errors"
	"net/http"
	"strconv"

	appregistrationcode "github.com/DEEIX-AI/DEEIX-Chat/backend/internal/application/registrationcode"
	"github.com/DEEIX-AI/DEEIX-Chat/backend/internal/repository"
	"github.com/DEEIX-AI/DEEIX-Chat/backend/internal/shared/response"
	"github.com/DEEIX-AI/DEEIX-Chat/backend/internal/transport/http/middleware"
	"github.com/gin-gonic/gin"
)

type Handler struct { service *appregistrationcode.Service }
func NewHandler(service *appregistrationcode.Service) *Handler { return &Handler{service: service} }

func (h *Handler) List(c *gin.Context) {
	page, pageSize := 1, 20
	if value, err := strconv.Atoi(c.Query("page")); err == nil && value > 0 { page = value }
	if value, err := strconv.Atoi(c.Query("page_size")); err == nil && value > 0 { pageSize = value }
	items, total, err := h.service.List(c.Request.Context(), page, pageSize, c.Query("status"))
	if err != nil { response.Error(c, http.StatusInternalServerError, "list registration codes failed"); return }
	views := make([]CodeResponse, 0, len(items)); for _, item := range items { views = append(views, toResponse(item)) }
	response.SuccessPage(c, total, views)
}

func (h *Handler) Create(c *gin.Context) {
	var req CreateRequest
	if err := c.ShouldBindJSON(&req); err != nil { response.InvalidRequestBody(c, err); return }
	items, err := h.service.Create(c.Request.Context(), middleware.MustUserID(c), req.Quantity)
	if err != nil { response.ErrorFrom(c, http.StatusBadRequest, err); return }
	views := make([]CodeResponse, 0, len(items)); for _, item := range items { views = append(views, toResponse(item)) }
	response.Success(c, gin.H{"results": views})
}

func (h *Handler) Disable(c *gin.Context) {
	id, err := parseID(c.Param("id")); if err != nil { response.Error(c, http.StatusBadRequest, "invalid registration code id"); return }
	if err = h.service.Disable(c.Request.Context(), id); err != nil { status := http.StatusInternalServerError; if errors.Is(err, repository.ErrNotFound) { status = http.StatusNotFound }; response.Error(c, status, "disable registration code failed"); return }
	response.Success(c, gin.H{"disabled": true})
}

func (h *Handler) Delete(c *gin.Context) {
	id, err := parseID(c.Param("id")); if err != nil { response.Error(c, http.StatusBadRequest, "invalid registration code id"); return }
	if err = h.service.Delete(c.Request.Context(), id); err != nil { status := http.StatusConflict; if errors.Is(err, repository.ErrNotFound) { status = http.StatusNotFound }; response.Error(c, status, "delete registration code failed"); return }
	response.Success(c, gin.H{"deleted": true})
}

func parseID(value string) (uint, error) { parsed, err := strconv.ParseUint(value, 10, 32); return uint(parsed), err }
