207		item := &domainuser.User{
208			PublicID:    conv.NormalizePublicID(uuid.NewString()),
209			Username:    username,
210			DisplayName: displayName,
211			Email:       "",
212			Role:        domainuser.RoleSuperAdmin,
213			Status:      domainuser.StatusActive,
214			Timezone:    "Etc/UTC",
215			Locale:      "en-US",
216		}
