218		if err = s.repo.CreateWithCredential(ctx, item, domainuser.Credential{
219			PasswordHash:      string(passwordHash),
220			PasswordAlgo:      "bcrypt",
221			PasswordEnabled:   true,
222			PasswordUpdatedAt: &now,
223			PasswordSetAt:     &now,
224			PasswordOrigin:    domainuser.PasswordOriginAdminCreated,
225			MustResetPassword: true,
226		}, 0, 0, nil, false); err != nil {
227			return nil, err
228		}
229		return &BootstrapSuperAdmin{Username: username, Password: bootstrapPassword}, nil
230	}
