241	func (s *Service) Login(
242		ctx context.Context,
243		username string,
244		password string,
245		requestID string,
246		auditCtx requestmeta.SessionAuditContext,
247	) (*LoginResult, error) {
248		normalizedAuditCtx := s.resolveSessionAuditContext(ctx, auditCtx)
249		result, err := s.doLogin(ctx, username, password, normalizedAuditCtx)
250		if err != nil {
251			reason := "invalid_credentials_or_inactive"
252			if errors.Is(err, ErrAccountLocked) {
253				reason = "account_locked"
254			}
255			s.RecordAuthEvent(
256				ctx, 0, requestID, "login", "failure", reason,
257				normalizedAuditCtx.ClientIP, normalizedAuditCtx.UserAgent,
258				marshalAuthEventDetail(map[string]string{"username": strings.TrimSpace(username)}),
259			)
260			return nil, err
261		}
262		if result.TwoFactorRequired {
263			s.RecordAuthEvent(
264				ctx, result.User.ID, requestID, "login", "challenge", "two_factor_required",
265				normalizedAuditCtx.ClientIP, normalizedAuditCtx.UserAgent,
266				marshalAuthEventDetail(map[string]string{"username": result.User.Username}),
267			)
268			return result, nil
269		}
270		s.RecordAuthEvent(
271			ctx, result.User.ID, requestID, "login", "success", "",
272			normalizedAuditCtx.ClientIP, normalizedAuditCtx.UserAgent,
273			marshalAuthEventDetail(map[string]interface{}{
274				"username":       result.User.Username,
275				"session_id":     result.SessionID,
276				"client_ip":      normalizedAuditCtx.ClientIP,
277				"location_label": normalizedAuditCtx.LocationLabel(),
278			}),
279		)
280		return result, nil
281	}
