389	func (s *Service) issueLoginResult(
390		ctx context.Context,
391		item *domainuser.User,
392		normalizedAuditCtx requestmeta.SessionAuditContext,
393		now time.Time,
394	) (*LoginResult, error) {
395		sessionID := uuid.NewString()
396		tokenBundle, err := s.buildSessionTokenPair(item, sessionID, now)
397		if err != nil {
398			return nil, err
399		}
400		sessionSnapshot := buildSessionAuditSnapshot(normalizedAuditCtx)
401	
402		session := &domainuser.Session{
403			SessionID:        sessionID,
404			UserID:           item.ID,
405			RefreshTokenHash: hashToken(tokenBundle.RefreshToken),
406			AccessJTI:        tokenBundle.AccessJTI,
407			ClientIP:         sessionSnapshot.ClientIP,
408			UserAgent:        sessionSnapshot.UserAgent,
409			DeviceName:       sessionSnapshot.DeviceName,
410			BrowserName:      sessionSnapshot.BrowserName,
411			OSName:           sessionSnapshot.OSName,
412			DeviceType:       sessionSnapshot.DeviceType,
413			GeoSource:        sessionSnapshot.GeoSource,
414			GeoAccuracy:      sessionSnapshot.GeoAccuracy,
415			CountryCode:      sessionSnapshot.CountryCode,
416			RegionName:       sessionSnapshot.RegionName,
417			CityName:         sessionSnapshot.CityName,
418			TimezoneName:     sessionSnapshot.TimezoneName,
419			IPLatitude:       sessionSnapshot.IPLatitude,
420			IPLongitude:      sessionSnapshot.IPLongitude,
421			IssuedAt:         now,
422			LastSeenAt:       &now,
423			ExpiresAt:        tokenBundle.RefreshExpiresAt,
424			RevokedAt:        nil,
425			RevokeReason:     "",
426		}
427		if err = s.repo.CreateSession(ctx, session); err != nil {
428			return nil, err
429		}
430	
431		if err = s.repo.UpdateLastLogin(ctx, item.ID); err != nil {
432			return nil, err
433		}
434	
435		userView, err := s.buildUserView(ctx, *item)
436		if err != nil {
437			return nil, err
438		}
439	
440		return &LoginResult{
441			AccessToken:      tokenBundle.AccessToken,
442			RefreshToken:     tokenBundle.RefreshToken,
443			SessionID:        sessionID,
444			ExpiresAt:        tokenBundle.ExpiresAt,
445			RefreshExpiresAt: tokenBundle.RefreshExpiresAt,
446			User:             userView,
447		}, nil
448	}
