477	// buildUserView 鍐呴儴鏋勫缓甯﹁闃呭揩鐓х殑鐢ㄦ埛瑙嗗浘銆?
478	func (s *Service) buildUserView(ctx context.Context, item domainuser.User) (userview.UserView, error) {
479		credential, credentialErr := s.repo.GetCredentialByUserID(ctx, item.ID)
480		if credentialErr != nil && !errors.Is(credentialErr, repository.ErrNotFound) {
481			return userview.UserView{}, credentialErr
482		}
483		if s.subscriptionResolver == nil {
484			view := userview.FromUser(item, nil)
485			s.applyCredentialView(&view, item, credential)
486			if err := s.applyTwoFactorView(ctx, &view); err != nil {
487				return userview.UserView{}, err
488			}
489			return view, nil
490		}
491	
492		subscription, err := s.subscriptionResolver.GetCurrentSubscriptionSnapshot(ctx, item.ID, time.Now())
493		if err != nil {
494			return userview.UserView{}, err
495		}
496		if subscription == nil {
497			view := userview.FromUser(item, nil)
498			s.applyCredentialView(&view, item, credential)
499			if err := s.applyTwoFactorView(ctx, &view); err != nil {
500				return userview.UserView{}, err
501			}
502			return view, nil
503		}
504	
505		view := userview.FromUser(item, &userview.SubscriptionState{
506			PlanID:    subscription.PlanID,
507			PlanName:  subscription.PlanName,
508			Tier:      subscription.Tier,
509			Status:    subscription.Status,
510			ExpiresAt: subscription.ExpiresAt,
511		})
512		s.applyCredentialView(&view, item, credential)
513		if err := s.applyTwoFactorView(ctx, &view); err != nil {
514			return userview.UserView{}, err
515		}
516		return view, nil
517	}
