519	func (s *Service) applyCredentialView(view *userview.UserView, item domainuser.User, credential *domainuser.Credential) {
520		if view == nil || credential == nil {
521			return
522		}
523		view.PasswordEnabled = credential.PasswordEnabled
524		view.PasswordSetAt = credential.PasswordSetAt
525		view.PasswordOrigin = credential.PasswordOrigin
526		view.MustResetPassword = credential.MustResetPassword || isBootstrapSuperAdminAdminCreatedPassword(item, credential)
527		view.InitialUsernameRequired = shouldRequireInitialUsername(item, s.cfg.Snapshot().AdminUsername)
528		view.InitialSecurityRequired = view.MustResetPassword || item.OnboardingCompletedAt == nil
529	}
