539	func (s *Service) CompleteOnboarding(
540		ctx context.Context,
541		userID uint,
542		newPassword string,
543		requestID string,
544		auditCtx requestmeta.SessionAuditContext,
545	) (*domainuser.User, bool, error) {
546		item, err := s.repo.GetByID(ctx, userID)
547		if err != nil {
548			return nil, false, err
549		}
550		credential, credentialErr := s.repo.GetCredentialByUserID(ctx, userID)
551		if credentialErr != nil && !errors.Is(credentialErr, repository.ErrNotFound) {
552			return nil, false, credentialErr
553		}
554		if shouldRequireInitialUsername(*item, s.cfg.Snapshot().AdminUsername) {
555			return nil, false, ErrUsernameChangeRequired
556		}
557		passwordChanged := false
558		if credential != nil && (credential.MustResetPassword || isBootstrapSuperAdminAdminCreatedPassword(*item, credential)) {
559			trimmedPassword, policyErr := userapp.NormalizePassword(newPassword)
560			if policyErr != nil {
561				return nil, false, policyErr
562			}
563			if isBootstrapSuperAdminAdminCreatedPassword(*item, credential) && passwordMatchesCredential(trimmedPassword, credential) {
564				return nil, false, fmt.Errorf("new password must be different from the bootstrap password")
565			}
566			passwordHash, hashErr := bcrypt.GenerateFromPassword([]byte(trimmedPassword), passwordHashCost)
567			if hashErr != nil {
568				return nil, false, hashErr
569			}
570			if err = s.repo.UpdatePassword(ctx, userID, string(passwordHash), domainuser.PasswordOriginUserSet, false); err != nil {
571				return nil, false, err
572			}
573			passwordChanged = true
574		}
575		now := time.Now()
576		completedAt := &now
577		updated, err := s.repo.UpdateProfile(ctx, userID, repository.UpdateUserFieldsInput{
578			OnboardingCompletedAt: &completedAt,
579		})
580		if err != nil {
581			return nil, passwordChanged, err
582		}
583		if passwordChanged {
584			if err = s.repo.RevokeAllSessions(ctx, userID, "password_change"); err != nil {
585				return nil, passwordChanged, err
586			}
587			normalizedAuditCtx := s.resolveSessionAuditContext(ctx, auditCtx)
588			s.RecordAuthEvent(
589				ctx, userID, requestID, "password_change", "success", "",
590				normalizedAuditCtx.ClientIP, normalizedAuditCtx.UserAgent,
591				marshalAuthEventDetail(map[string]interface{}{"initial_onboarding": true}),
592			)
593		}
594		return updated, passwordChanged, nil
595	}
596	
597	func isBootstrapSuperAdminAdminCreatedPassword(item domainuser.User, credential *domainuser.Credential) bool {
598		return credential != nil &&
599			item.Role == domainuser.RoleSuperAdmin &&
600			credential.PasswordEnabled &&
601			credential.PasswordOrigin == domainuser.PasswordOriginAdminCreated
602	}
