604	func passwordMatchesCredential(password string, credential *domainuser.Credential) bool {
605		if credential == nil || strings.TrimSpace(credential.PasswordHash) == "" {
606			return false
607		}
608		return bcrypt.CompareHashAndPassword([]byte(credential.PasswordHash), []byte(password)) == nil
609	}
