631	// resolveSessionAuditContext 鏍囧噯鍖栧璁′笂涓嬫枃锛屽苟鍦ㄦ棤鍦扮悊淇℃伅鏃跺皾璇曢€氳繃 GeoIP 琛ュ叏銆?
632	func (s *Service) resolveSessionAuditContext(
633		ctx context.Context,
634		auditCtx requestmeta.SessionAuditContext,
635	) requestmeta.SessionAuditContext {
636		normalized := auditCtx.Normalize()
637		if normalized.CountryCode != "" || normalized.RegionName != "" || normalized.CityName != "" || normalized.TimezoneName != "" {
638			return normalized
639		}
640		if s.geoResolver == nil {
641			return normalized
642		}
643	
644		enriched, err := s.geoResolver.Lookup(ctx, normalized.ClientIP)
645		if err != nil {
646			return normalized
647		}
648		return mergeSessionAuditContext(normalized, enriched)
