770	func normalizeAppearancePreferences(raw string) (string, error) {
771		if raw == "" {
772			return "", nil
773		}
774	
775		var payload map[string]string
776		if err := json.Unmarshal([]byte(raw), &payload); err != nil {
777			return "", ErrInvalidAppearancePreferences
778		}
779	
780		normalized := make(map[string]string, len(payload))
781		for key, value := range payload {
782			switch key {
783			case "theme":
784				if value != "light" && value != "dark" && value != "system" {
785					return "", ErrInvalidAppearancePreferences
786				}
787				normalized[key] = value
788			case "preset":
789				if value != "default" && value != "azure" && value != "cobalt" && value != "graphite" && value != "lagoon" && value != "ink" && value != "ochre" && value != "sepia" {
790					return "", ErrInvalidAppearancePreferences
791				}
792				normalized[key] = value
793			case "chatFont":
794				if value != "default" && value != "songti" && value != "heiti" && value != "mono" {
795					return "", ErrInvalidAppearancePreferences
796				}
797				normalized[key] = value
798			case "chatFontWeight":
799				if value != "regular" && value != "medium" && value != "semibold" && value != "bold" {
800					return "", ErrInvalidAppearancePreferences
801				}
802				normalized[key] = value
803			case "fontSize":
804				if value != "small" && value != "standard" && value != "medium" && value != "large" {
805					value = "standard"
806				}
807				normalized[key] = value
808			default:
809				return "", ErrInvalidAppearancePreferences
810			}
811		}
812	
813		next, err := json.Marshal(normalized)
814		if err != nil {
815			return "", ErrInvalidAppearancePreferences
816		}
817		return string(next), nil
818	}
