822		if trimmed == "" {
823			return "en-US", nil
824		}
825		normalized := strings.ReplaceAll(trimmed, "_", "-")
826		switch normalized {
827		case "en", "en-US", "zh", "zh-CN":
828			return normalized, nil
829		default:
830			return "", ErrInvalidLocale
831		}
832	}
