859	func (s *Service) DeleteAccount(
860		ctx context.Context,
861		userID uint,
862		verificationMethod string,
863		code string,
864		requestID string,
865		auditCtx requestmeta.SessionAuditContext,
866	) error {
867		item, err := s.repo.GetByID(ctx, userID)
868		if err != nil {
