870		}
871		if item.Role == domainuser.RoleSuperAdmin {
872			return ErrDeleteSuperAdminNotAllowed
873		}
874		methods, err := s.resolveSecurityVerificationMethods(ctx, item)
875		if err != nil {
876			return err
877		}
878		method := methods[0]
879		if normalizedMethod := normalizeSecurityVerificationMethod(verificationMethod); normalizedMethod != "" {
880			method = normalizedMethod
881		}
882		if method == SecurityVerificationMethodNone {
883			return ErrAccountDeleteVerificationRequired
884		}
885		if !containsSecurityVerificationMethod(methods, method) {
886			return fmt.Errorf("verification method is unavailable")
887		}
888		normalizedEmail := ""
889		if method == SecurityVerificationMethodEmail {
890			normalizedEmail, err = normalizeRegistrationEmail(item.Email)
891			if err != nil {
892				return fmt.Errorf("user email is invalid")
893			}
894		}
895		if err = s.verifySecurityCodeWithMethod(ctx, item, method, domainuser.ContactVerificationPurposeAccountDelete, normalizedEmail, code, time.Now()); err != nil {
896			return fmt.Errorf("verification code is invalid or expired")
897		}
898	
899		normalizedAuditCtx := s.resolveSessionAuditContext(ctx, auditCtx)
900		storagePaths, err := s.repo.ListDistinctFileStoragePathsByUserID(ctx, userID)
901		if err != nil {
902			s.RecordAuthEvent(
903				ctx,
904				userID,
905				requestID,
906				"account_delete",
907				"failure",
908				"list_storage_paths_failed",
909				normalizedAuditCtx.ClientIP,
910				normalizedAuditCtx.UserAgent,
911				marshalAuthEventDetail(map[string]interface{}{
912					"user_id":   userID,
913					"username":  item.Username,
914					"public_id": item.PublicID,
915				}),
916			)
917			return err
918		}
919	
920		if err = s.repo.DeleteAccountHard(ctx, userID); err != nil {
921			s.RecordAuthEvent(
922				ctx,
923				userID,
924				requestID,
925				"account_delete",
926				"failure",
927				"delete_account_failed",
928				normalizedAuditCtx.ClientIP,
929				normalizedAuditCtx.UserAgent,
930				marshalAuthEventDetail(map[string]interface{}{
931					"user_id":            userID,
932					"username":           item.Username,
933					"public_id":          item.PublicID,
934					"storage_file_count": len(storagePaths),
935				}),
936			)
937			return err
938		}
939	
940		failedPaths := s.cleanupDeletedAccountFiles(ctx, storagePaths)
941		s.RecordAuthEvent(
942			ctx,
943			userID,
944			requestID,
945			"account_delete",
946			"success",
947			"",
948			normalizedAuditCtx.ClientIP,
949			normalizedAuditCtx.UserAgent,
950			marshalAuthEventDetail(map[string]interface{}{
951				"user_id":                  userID,
952				"username":                 item.Username,
953				"public_id":                item.PublicID,
954				"client_ip":                normalizedAuditCtx.ClientIP,
955				"location":                 normalizedAuditCtx.LocationLabel(),
956				"storage_file_count":       len(storagePaths),
957				"storage_cleanup_failures": len(failedPaths),
958			}),
959		)
960		if len(failedPaths) > 0 {
961			s.RecordAuthEvent(
962				ctx,
963				userID,
964				requestID,
965				"account_delete_cleanup",
966				"failure",
967				"storage_cleanup_failed",
968				normalizedAuditCtx.ClientIP,
969				normalizedAuditCtx.UserAgent,
970				marshalAuthEventDetail(map[string]interface{}{
971					"user_id":           userID,
972					"failed_path_count": len(failedPaths),
973					"failed_paths":      trimStringSlice(failedPaths, 10),
974				}),
975			)
976		}
977	
978		return nil
979	}
