1014	// cleanupDeletedAccountFiles 浠庡璞″瓨鍌ㄥ垹闄ょ敤鎴锋枃浠讹紝杩斿洖鍒犻櫎澶辫触鐨勮矾寰勫垪琛ㄣ€?
1015	func (s *Service) cleanupDeletedAccountFiles(ctx context.Context, storagePaths []string) []string {
1016		if s.storeProvider == nil {
1017			s.storeProvider = appstorage.NewRuntimeProvider(s.cfg, nil)
1018		}
1019		store, err := s.storeProvider.Open(ctx)
1020		if err != nil {
1021			return append([]string(nil), storagePaths...)
1022		}
1023		seen := make(map[string]struct{}, len(storagePaths))
1024		failed := make([]string, 0)
1025		for _, rawPath := range storagePaths {
1026			normalizedPath := strings.TrimSpace(rawPath)
1027			if normalizedPath == "" {
1028				continue
1029			}
1030			if _, ok := seen[normalizedPath]; ok {
1031				continue
1032			}
1033			seen[normalizedPath] = struct{}{}
1034	
1035			if err := store.Delete(ctx, normalizedPath); err != nil {
1036				failed = append(failed, normalizedPath)
1037			}
1038		}
1039		sort.Strings(failed)
1040		return failed
1041	}
