1051	// Refresh 浣跨敤 refresh token 杞崲骞剁鍙戞柊鐨?access/refresh銆?
1052	func (s *Service) Refresh(
1053		ctx context.Context,
1054		refreshToken string,
1055		requestID string,
1056		auditCtx requestmeta.SessionAuditContext,
1057	) (*LoginResult, error) {
1058		normalizedAuditCtx := s.resolveSessionAuditContext(ctx, auditCtx)
1059		trimmedRefreshToken := strings.TrimSpace(refreshToken)
1060		cfg := s.cfg.Snapshot()
1061		claims, err := token.Parse(cfg.JWTSecret, trimmedRefreshToken)
1062		if err != nil {
1063			s.RecordAuthEvent(ctx, 0, requestID, "token_refresh", "failure", "invalid_refresh_token_parse", normalizedAuditCtx.ClientIP, normalizedAuditCtx.UserAgent, "")
1064			return nil, ErrInvalidRefreshToken
1065		}
1066		if claims.TokenType != "refresh" || claims.SessionID == "" || claims.UserID == 0 {
1067			s.RecordAuthEvent(ctx, claims.UserID, requestID, "token_refresh", "failure", "invalid_refresh_claims", normalizedAuditCtx.ClientIP, normalizedAuditCtx.UserAgent, "")
1068			return nil, ErrInvalidRefreshToken
1069		}
1070	
1071		session, err := s.repo.GetSessionByUserAndSessionID(ctx, claims.UserID, claims.SessionID)
1072		if err != nil {
1073			if errors.Is(err, repository.ErrNotFound) {
1074				s.RecordAuthEvent(ctx, claims.UserID, requestID, "token_refresh", "failure", "session_not_found", normalizedAuditCtx.ClientIP, normalizedAuditCtx.UserAgent, "")
1075				return nil, ErrInvalidRefreshToken
1076			}
1077			return nil, err
1078		}
1079		if session.RevokedAt != nil || time.Now().After(session.ExpiresAt) {
1080			s.RecordAuthEvent(ctx, claims.UserID, requestID, "token_refresh", "failure", "session_revoked_or_expired", normalizedAuditCtx.ClientIP, normalizedAuditCtx.UserAgent, "")
1081			return nil, ErrSessionRevoked
1082		}
1083	
1084		userItem, err := s.repo.GetByID(ctx, claims.UserID)
1085		if err != nil {
1086			return nil, err
1087		}
1088		if userItem.Status != domainuser.StatusActive {
1089			s.RecordAuthEvent(ctx, claims.UserID, requestID, "token_refresh", "failure", "user_not_active", normalizedAuditCtx.ClientIP, normalizedAuditCtx.UserAgent, "")
1090			return nil, ErrSessionRevoked
1091		}
1092	
1093		now := time.Now()
1094		tokenBundle, err := s.buildSessionTokenPair(userItem, claims.SessionID, now)
1095		if err != nil {
1096			return nil, err
1097		}
1098	
1099		if err = s.repo.RotateSessionTokens(
1100			ctx,
1101			repository.RotateSessionTokensInput{
1102				UserID:               userItem.ID,
1103				SessionID:            claims.SessionID,
1104				PresentedRefreshHash: hashToken(trimmedRefreshToken),
1105				NextRefreshHash:      hashToken(tokenBundle.RefreshToken),
1106				NextAccessJTI:        tokenBundle.AccessJTI,
1107				IssuedAt:             now,
1108				ExpiresAt:            tokenBundle.RefreshExpiresAt,
1109				Now:                  now,
1110				PreviousTokenGrace:   refreshTokenPreviousHashGrace,
1111			},
1112		); err != nil {
1113			if errors.Is(err, repository.ErrInvalidInput) {
1114				s.RecordAuthEvent(ctx, claims.UserID, requestID, "token_refresh", "failure", "refresh_token_hash_mismatch", normalizedAuditCtx.ClientIP, normalizedAuditCtx.UserAgent, "")
1115				return nil, ErrInvalidRefreshToken
1116			}
1117			return nil, err
1118		}
1119	
1120		sessionSnapshot := buildSessionAuditSnapshot(normalizedAuditCtx)
1121		if err = s.repo.TouchSessionActivity(ctx, userItem.ID, claims.SessionID, sessionActivityInputFromSnapshot(sessionSnapshot, now)); err != nil {
1122			return nil, err
1123		}
1124	
1125		s.RecordAuthEvent(
1126			ctx,
1127			userItem.ID,
1128			requestID,
1129			"token_refresh",
1130			"success",
1131			"",
1132			sessionSnapshot.ClientIP,
1133			sessionSnapshot.UserAgent,
1134			marshalSessionAuthEventDetail(claims.SessionID, sessionSnapshot),
1135		)
1136	
1137		userView, err := s.buildUserView(ctx, *userItem)
1138		if err != nil {
1139			return nil, err
1140		}
1141	
1142		return &LoginResult{
1143			AccessToken:      tokenBundle.AccessToken,
1144			RefreshToken:     tokenBundle.RefreshToken,
1145			SessionID:        claims.SessionID,
1146			ExpiresAt:        tokenBundle.ExpiresAt,
1147			RefreshExpiresAt: tokenBundle.RefreshExpiresAt,
1148			User:             userView,
1149		}, nil
1150	}
