1532		}
1533		refreshToken, err := token.GenerateWithClaims(
1534			cfg.JWTSecret,
1535			user.ID,
1536			user.Username,
1537			user.Role,
1538			sessionID,
1539			refreshJTI,
1540			"refresh",
1541			refreshTTL,
1542		)
1543		if err != nil {
