87					return err
88				}
89				if !entity.BuiltIn {
90					if err := tx.Model(&entity).Update("built_in", true).Error; err != nil {
91						return err
92					}
93				}
94			}
95	
96			var vendorKeys []string
97			if err := tx.Model(&model.LLMPlatformModel{}).
98				Distinct("vendor").
99				Where("vendor <> ?", "").
100				Pluck("vendor", &vendorKeys).Error; err != nil {
101				return err
102			}
103			for _, key := range vendorKeys {
104				entity := model.LLMModelVendor{Key: key, Name: key}
105				if err := tx.Where("key = ?", key).Attrs(entity).FirstOrCreate(&entity).Error; err != nil {
106					return err
107				}
108			}
109			return nil
110		})
