132	// backfillContextArtifactMessageIDs 灏嗘棫璇佹嵁缁熶竴杩佺Щ鍒颁骇鐢熻璇佹嵁鐨勫姪鎵嬭繍琛岃妭鐐广€?
133	// 鍚屼竴娆＄敓鎴愮殑 user/assistant 娑堟伅鍏变韩 run_id锛涗粎鍦ㄥ敮涓€鍖归厤鍔╂墜娑堟伅鏃跺洖濉紝寮傚父閲嶅 run 鏁版嵁淇濇寔涓嶅彉銆?
134	func backfillContextArtifactMessageIDs(db *gorm.DB) error {
135		if !db.Migrator().HasTable(&model.ChatContextRecord{}) || !db.Migrator().HasTable(&model.Message{}) {
136			return nil
137		}
138		return db.Exec(`
139			WITH artifacts_to_backfill AS (
140				SELECT records.id, records.run_id, records.conversation_id, records.user_id
141				FROM chat_context_records AS records
142				LEFT JOIN chat_messages AS current_owner
143					ON current_owner.id = records.message_id
144					AND current_owner.run_id = records.run_id
145					AND current_owner.conversation_id = records.conversation_id
146					AND current_owner.user_id = records.user_id
147					AND current_owner.role = 'assistant'
148					AND current_owner.deleted_at IS NULL
149				WHERE records.record_type = 'artifact'
150					AND records.run_id <> ''
151					AND records.deleted_at IS NULL
152					AND current_owner.id IS NULL
153			),
154			unique_assistant_run_owners AS (
155				SELECT artifacts.id AS record_id, MIN(messages.id) AS message_id
156				FROM artifacts_to_backfill AS artifacts
157				JOIN chat_messages AS messages
158					ON messages.run_id = artifacts.run_id
159					AND messages.conversation_id = artifacts.conversation_id
160					AND messages.user_id = artifacts.user_id
161					AND messages.role = 'assistant'
162					AND messages.deleted_at IS NULL
163				GROUP BY artifacts.id
164				HAVING COUNT(*) = 1
165			)
166			UPDATE chat_context_records
167			SET message_id = (
168				SELECT owners.message_id
169				FROM unique_assistant_run_owners AS owners
170				WHERE owners.record_id = chat_context_records.id
171			)
172			WHERE EXISTS (
173					SELECT 1
174					FROM unique_assistant_run_owners AS owners
175					WHERE owners.record_id = chat_context_records.id
176				)
177		`).Error
178	}
