403	// Run 鍚姩 HTTP 鏈嶅姟骞舵敮鎸佷紭闆呭仠鏈恒€?
404	func (a *App) Run() error {
405		addr := fmt.Sprintf(":%s", a.cfg.HTTPPort)
406		srv := &http.Server{
407			Addr:              addr,
408			Handler:           a.engine,
409			ReadHeaderTimeout: httpTimeoutSeconds(a.cfg.HTTPReadHeaderTimeoutSeconds, 10),
410			ReadTimeout:       httpTimeoutSeconds(a.cfg.HTTPReadTimeoutSeconds, 120),
411			IdleTimeout:       httpTimeoutSeconds(a.cfg.HTTPIdleTimeoutSeconds, 120),
412			MaxHeaderBytes:    httpMaxHeaderBytes(a.cfg.HTTPMaxHeaderBytes),
413		}
414	
415		errCh := make(chan error, 1)
416		go func() {
417			a.logger.Info("server_starting", zap.String("port", a.cfg.HTTPPort))
418			if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
419				errCh <- err
420			}
421			close(errCh)
422		}()
423	
424		quit := make(chan os.Signal, 1)
425		signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
426	
427		select {
428		case err := <-errCh:
429			return err
430		case sig := <-quit:
431			a.logger.Info("server_shutting_down", zap.String("signal", sig.String()))
432		}
433	
434		if a.backgroundCancel != nil {
435			a.backgroundCancel()
436		}
437		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
438		defer cancel()
439		if err := srv.Shutdown(ctx); err != nil {
440			a.logger.Error("server_shutdown_error", zap.Error(err))
441			return err
442		}
443		a.logger.Info("server_stopped")
444		return nil
445	}
446	
447	func httpTimeoutSeconds(value int, fallback int) time.Duration {
448		if value <= 0 {
449			value = fallback
450		}
451		return time.Duration(value) * time.Second
452	}
453	
454	func httpMaxHeaderBytes(value int) int {
455		if value <= 0 {
456			return 1 << 20
457		}
458		return value
459	}
