223	func registerFrontendStatic(engine *gin.Engine, distDir string, log *zap.Logger) {
224		root := strings.TrimSpace(distDir)
225		if root == "" {
226			return
227		}
228	
229		absoluteRoot, err := filepath.Abs(root)
230		if err != nil {
231			if log != nil {
232				log.Warn("frontend_static_path_invalid", zap.String("path", root), zap.Error(err))
233			}
234			return
235		}
236	
237		info, err := os.Stat(absoluteRoot)
238		if err != nil || !info.IsDir() {
239			if log != nil {
240				log.Warn("frontend_static_disabled", zap.String("path", absoluteRoot), zap.Error(err))
241			}
242			return
243		}
244	
245		if log != nil {
246			log.Info("frontend_static_enabled", zap.String("path", absoluteRoot))
247		}
248	
249		engine.NoRoute(func(c *gin.Context) {
250			requestPath := cleanFrontendPath(c.Request.URL.Path)
251			if isBackendOnlyPath(requestPath) {
252				response.ErrorWithCode(c, http.StatusNotFound, response.CodeResourceNotFound, "not found")
253				return
254			}
255	
256			if filePath, ok := resolveFrontendStaticFile(absoluteRoot, requestPath); ok {
257				applyFrontendCacheHeaders(c, requestPath)
258				c.File(filePath)
259				return
260			}
261	
262			if filePath, ok := resolveFrontendPageFile(absoluteRoot, requestPath); ok {
263				c.Header("Cache-Control", "no-cache")
264				c.File(filePath)
265				return
266			}
267	
268			notFoundPath := filepath.Join(absoluteRoot, "404.html")
269			if isRegularFile(notFoundPath) {
270				c.Status(http.StatusNotFound)
271				c.File(notFoundPath)
272				return
273			}
274	
275			response.ErrorWithCode(c, http.StatusNotFound, response.CodeResourceNotFound, "not found")
276		})
277	}
