288	func cleanFrontendPath(rawPath string) string {
289		if rawPath == "" || rawPath == "/" {
290			return "/"
291		}
292		return path.Clean("/" + strings.TrimPrefix(rawPath, "/"))
293	}
294	
295	func isBackendOnlyPath(requestPath string) bool {
296		return requestPath == "/api" ||
297			strings.HasPrefix(requestPath, "/api/") ||
298			requestPath == "/swagger" ||
299			strings.HasPrefix(requestPath, "/swagger/") ||
300			requestPath == "/healthz" ||
301			requestPath == "/readyz"
302	}
303	
304	func resolveFrontendStaticFile(root string, requestPath string) (string, bool) {
305		if requestPath == "/" {
306			return "", false
307		}
308		candidate := filepath.Join(root, filepath.FromSlash(strings.TrimPrefix(requestPath, "/")))
309		if !strings.HasPrefix(candidate, root) {
310			return "", false
311		}
312		if isRegularFile(candidate) {
313			return candidate, true
314		}
315		return "", false
316	}
317	
318	func resolveFrontendPageFile(root string, requestPath string) (string, bool) {
319		candidates := []string{filepath.Join(root, "index.html")}
320		if requestPath != "/" {
321			cleanPath := filepath.FromSlash(strings.TrimPrefix(requestPath, "/"))
322			candidates = []string{
323				filepath.Join(root, cleanPath+".html"),
324				filepath.Join(root, cleanPath, "index.html"),
325				filepath.Join(root, "index.html"),
326			}
327		}
328	
329		for _, candidate := range candidates {
330			if strings.HasPrefix(candidate, root) && isRegularFile(candidate) {
331				return candidate, true
332			}
333		}
334		return "", false
335	}
336	
337	func isRegularFile(filePath string) bool {
338		info, err := os.Stat(filePath)
339		return err == nil && !info.IsDir()
340	}
341	
342	func applyFrontendCacheHeaders(c *gin.Context, requestPath string) {
343		if isImmutableFrontendAsset(requestPath) {
344			c.Header("Cache-Control", "public, max-age=31536000, immutable")
345			return
346		}
347		if isVendorIconAsset(requestPath) {
348			c.Header("Cache-Control", "public, max-age=86400, stale-while-revalidate=604800")
349			return
350		}
351		if isNextExportDataAsset(requestPath) {
352			c.Header("Cache-Control", "public, max-age=86400, stale-while-revalidate=604800")
353			return
354		}
355		c.Header("Cache-Control", "public, max-age=3600")
356	}
357	
358	func isImmutableFrontendAsset(requestPath string) bool {
359		return strings.HasPrefix(requestPath, "/_next/static/") ||
360			strings.HasPrefix(requestPath, "/fonts/")
361	}
362	
363	func isVendorIconAsset(requestPath string) bool {
364		return strings.HasPrefix(requestPath, "/vendor/lobehub-icons/")
365	}
366	
367	func isNextExportDataAsset(requestPath string) bool {
368		fileName := path.Base(requestPath)
369		return strings.HasPrefix(fileName, "__next.") && strings.EqualFold(path.Ext(fileName), ".txt")
370	}
