372	func readyzHandler(hc HealthChecker) gin.HandlerFunc {
373		return func(c *gin.Context) {
374			ctx, cancel := context.WithTimeout(c.Request.Context(), 5*time.Second)
375			defer cancel()
376	
377			var healthy bool
378			checksMap := gin.H{}
379	
380			if hc != nil {
381				results, ok := hc.CheckHealth(ctx)
382				healthy = ok
383				for _, r := range results {
384					checksMap[r.Name] = r.Status
385				}
386			} else {
387				healthy = true
388			}
389	
390			status := http.StatusOK
391			if !healthy {
392				status = http.StatusServiceUnavailable
393			}
394			c.JSON(status, gin.H{
395				"status": map[bool]string{true: "ok", false: "degraded"}[healthy],
396				"checks": checksMap,
397			})
398		}
399	}

