func SeedModelVendors(db *gorm.DB) error {
	return db.Transaction(func(tx *gorm.DB) error {
		for _, item := range domainchannel.BuiltInModelVendors() {
			entity := model.LLMModelVendor{
				Key:       item.Key,
				Name:      item.Name,
				Icon:      item.Icon,
