                  className="mt-2 h-9 w-full text-xs text-muted-foreground shadow-none"
                  onClick={cancelTwoFactorChallenge}
                >
                  {passwordLoginEnabled ? t("backToPasswordLogin") : t("backToLoginMethods")}
                </Button>
              </>
            ) : null}

            {mode === "login" && !twoFactorChallengeToken && passwordLoginEnabled ? (
              <form className="mt-7 space-y-4" onSubmit={onLoginSubmit}>
                <div className="space-y-2">
                  <label className="text-sm font-medium leading-none text-foreground" htmlFor="username">
                    {accountLabel}
                  </label>
                  <Input
                    id="username"
                    name="username"
                    autoComplete="username"
                    className="h-9 border-input/50"
                    placeholder={accountPlaceholder}
                    value={username}
                    onChange={(event) => setUsername(event.target.value)}
                    required
                  />
                </div>
                <div className="space-y-2">
                  <div className="flex items-center justify-between gap-3">
                    <label className="text-sm font-medium leading-none text-foreground" htmlFor="password">
                      {t("password")}
                    </label>
                    {passwordResetEnabled ? (
                      <button
                        type="button"
                        className="text-xs font-medium text-muted-foreground underline-offset-4 transition-colors hover:text-foreground hover:underline focus-visible:text-foreground focus-visible:underline focus-visible:outline-none"
                        onClick={() => {
                          updateResetEmail(username.includes("@") ? username : "");
                          loginPage.setMode("reset-password");
                        }}
                      >
                        {t("forgotPassword")}
                      </button>
                    ) : null}
                  </div>
                  <Input
                    id="password"
                    name="password"
                    type="password"
                    autoComplete="current-password"
                    className="h-9 border-input/50"
                    placeholder={t("password")}
                    value={password}
                    onChange={(event) => setPassword(event.target.value)}
                    required
                  />
                </div>
                <Button
                  className="mt-2 h-9 w-full rounded-md bg-foreground text-sm font-semibold text-background shadow-none hover:bg-foreground/90"
                  type="submit"
                  disabled={submitting}
                >
                  {submitting ? <SpinnerLabel>{t("signingIn")}</SpinnerLabel> : t("signIn")}
                </Button>
              </form>
            ) : null}

            {mode === "reset-password" && passwordResetEnabled ? (
              <>
                <form className="mt-7 space-y-4" onSubmit={onPasswordResetSubmit}>
                  <div className="space-y-2">
                    <label className="text-sm font-medium leading-none text-foreground" htmlFor="reset-email">
                      {t("email")}
                    </label>
                    <Input
                      id="reset-email"
                      type="email"
                      autoComplete="email"
                      className="h-9 border-input/50"
                      placeholder={t("email")}
                      value={resetEmail}
                      onChange={(event) => updateResetEmail(event.target.value)}
                      required
                    />

          setTwoFactorVerificationMethods(["two_factor"]);
          setTwoFactorVerificationMethod("two_factor");
          setTwoFactorCode("");
          setTwoFactorEmailDebugCode("");
          setTwoFactorEmailCodeResendAt(0);
          toast.error(t("toasts.challengeExpired"));
          return;
        }
        toast.error(resolveErrorMessage(error, t("toasts.loginRetry")));
      } finally {
        setSubmitting(false);
      }
    },
    [completeAuth, password, resolveErrorMessage, submitting, t, twoFactorChallengeToken, twoFactorCode, twoFactorVerificationMethod, username],
  );

  const handleProviderLogin = React.useCallback(async (slug: string, intent: ProviderAuthIntent = "login") => {
    try {
      const redirectURI = `${window.location.origin}/auth/callback?provider=${encodeURIComponent(slug)}`;
      const pkce = await createProviderPKCE();
      if (!options.providerAuthBridge.enabled) {
        const params = new URLSearchParams();
        window.sessionStorage.setItem(providerPKCEStorageKey(slug), pkce.verifier);
        params.set("redirect_uri", redirectURI);
        params.set("next", resolvedNextPath);
        params.set("code_challenge", pkce.challenge);
        params.set("intent", intent);
        if (registrationCode.trim()) params.set("registration_code", registrationCode.trim());
        window.location.href = `${resolveApiBaseURL()}/api/v1/auth/providers/${encodeURIComponent(slug)}/start?${params.toString()}`;
        return;
      }
      const clientState = createProviderClientState();
      window.sessionStorage.setItem(providerAuthBridgeStorageKey(slug), JSON.stringify({
        verifier: pkce.verifier,
        state: clientState,
        intent,
        next: resolvedNextPath,
        registrationCode: registrationCode.trim(),
      }));
      const result = await startProviderAuthBridge(slug, {
        clientID: "deeix-web",
        redirectURI,
        codeChallenge: pkce.challenge,
        clientState,
        intent,
        next: resolvedNextPath,
        registrationCode: registrationCode.trim(),
      });
      // OAuth must use a full document navigation so the provider redirect can leave the app origin.
      window.location.href = result.authorizationURL;
    } catch {
      window.sessionStorage.removeItem(providerAuthBridgeStorageKey(slug));
      window.sessionStorage.removeItem(providerPKCEStorageKey(slug));
      toast.error(t("toasts.providerStartFailed"));
    }
  }, [options.providerAuthBridge.enabled, registrationCode, resolvedNextPath, t]);

  const requestRegisterCode = React.useCallback(async () => {
    if (!emailVerificationEnabled || sendingCode || registerCodeCooldownSeconds > 0) {
      return;
    }
    if (registerTurnstileRequired && !registerTurnstileToken) {
      toast.error(t("toasts.turnstileRequired"));
      return;
    }
    setSendingCode(true);
    try {
      const result = await startEmailRegistration(registerEmail, registerTurnstileRequired ? registerTurnstileToken : undefined);
      setCodeSent(result.sent);
      setRegisterDebugCode(result.debugCode ?? "");
      if (result.sent) {
        const now = Date.now();
        setCooldownNow(now);
        setRegisterCodeResendAt(now + VERIFICATION_CODE_RESEND_COOLDOWN_MS);
      }
    } catch (error) {
      toast.error(resolveErrorMessage(error, t("toasts.codeSendFailed")));
    } finally {
      if (registerTurnstileRequired && registerTurnstileToken) {
        resetRegisterTurnstile();
      }
      setSendingCode(false);
    }
  }, [emailVerificationEnabled, registerCodeCooldownSeconds, registerEmail, registerTurnstileRequired, registerTurnstileToken, resetRegisterTurnstile, resolveErrorMessage, sendingCode, t]);

  const requestTwoFactorEmailCode = React.useCallback(async () => {
    if (!twoFactorChallengeToken || twoFactorVerificationMethod !== "email" || sendingCode || twoFactorEmailCodeCooldownSeconds > 0) {
      return;
    }
    setSendingCode(true);
    setTwoFactorEmailDebugCode("");
    try {
      const result = await startTwoFactorEmailVerification(twoFactorChallengeToken);
      setTwoFactorEmailDebugCode(result.debugCode ?? "");
      if (result.sent) {
        const now = Date.now();
        setCooldownNow(now);
        setTwoFactorEmailCodeResendAt(now + VERIFICATION_CODE_RESEND_COOLDOWN_MS);
      }
    } catch (error) {
      toast.error(resolveErrorMessage(error, t("toasts.codeSendFailed")));
    } finally {
      setSendingCode(false);
    }
  }, [resolveErrorMessage, sendingCode, t, twoFactorChallengeToken, twoFactorEmailCodeCooldownSeconds, twoFactorVerificationMethod]);

  const requestPasswordResetCode = React.useCallback(async () => {
    if (!passwordResetEnabled || sendingCode || resetCodeCooldownSeconds > 0) {
      return;
    }
    setSendingCode(true);
    try {
      const result = await startPasswordReset(resetEmail);
      setResetCodeSent(result.sent);
      if (result.sent) {
        const now = Date.now();
        setCooldownNow(now);
        setResetCodeResendAt(now + VERIFICATION_CODE_RESEND_COOLDOWN_MS);
      }
    } catch (error) {
      toast.error(resolveErrorMessage(error, t("toasts.passwordResetCodeFailed")));
    } finally {
      setSendingCode(false);
    }
  }, [passwordResetEnabled, resetCodeCooldownSeconds, resetEmail, resolveErrorMessage, sendingCode, t]);

  const onRegisterSubmit = React.useCallback(
    async (event: React.FormEvent<HTMLFormElement>) => {
      event.preventDefault();
      if (submitting) {
        return;
      }
      if (!isPasswordPolicyValid(registerPassword)) {
        toast.error(t("toasts.passwordInvalid"));
        return;
      }
      if (registerTurnstileRequired && !registerTurnstileToken) {
        toast.error(t("toasts.turnstileRequired"));
        return;
      }
      setSubmitting(true);
      try {
        const result = await completeEmailRegistration(
          registerEmail,
          registerPassword,
          emailVerificationEnabled ? registerCode : "",
          registrationCode,
          registerTurnstileRequired ? registerTurnstileToken : undefined,
        );
        completeAuth(result.accessToken, result.sessionID);
      } catch (error) {
        toast.error(resolveErrorMessage(error, t("toasts.registerFailed")));
      } finally {
        if (registerTurnstileRequired && registerTurnstileToken) {
          resetRegisterTurnstile();
        }
        setSubmitting(false);
      }
    },
    [completeAuth, emailVerificationEnabled, registerCode, registerEmail, registerPassword, registrationCode, registerTurnstileRequired, registerTurnstileToken, resetRegisterTurnstile, resolveErrorMessage, submitting, t],
  );

  const onPasswordResetSubmit = React.useCallback(
    async (event: React.FormEvent<HTMLFormElement>) => {
      event.preventDefault();
      if (submitting) {
        return;
      }
      if (!isPasswordPolicyValid(resetPassword)) {
        toast.error(t("toasts.passwordInvalid"));
        return;
      }
      if (resetCode.length !== 6) {
        toast.error(t("toasts.codeRequired"));
        return;
      }
      setSubmitting(true);
      try {
        await completePasswordReset(resetEmail, resetCode, resetPassword);
        setUsername(resetEmail.trim());
        setPassword("");
        setResetPassword("");
        setResetCode("");
        setResetCodeSent(false);
        setResetCodeResendAt(0);
        setMode("login");
        toast.success(t("toasts.passwordResetSuccess"));
      } catch (error) {
        toast.error(resolveErrorMessage(error, t("toasts.passwordResetFailed")));
      } finally {
        setSubmitting(false);
      }
    },
    [resetCode, resetEmail, resetPassword, resolveErrorMessage, submitting, t],
  );

  const updateRegisterEmail = React.useCallback((value: string) => {
    setRegisterEmail(value);
    setCodeSent(false);
    setRegisterDebugCode("");
    setRegisterCodeResendAt(0);
  }, []);

  const updateResetEmail = React.useCallback((value: string) => {
    setResetEmail(value);
    setResetCodeSent(false);
    setResetCodeResendAt(0);
  }, []);

  const cancelTwoFactorChallenge = React.useCallback(() => {
    setTwoFactorChallengeToken("");
    setTwoFactorVerificationMethods(["two_factor"]);
    setTwoFactorVerificationMethod("two_factor");
    setTwoFactorCode("");
    setTwoFactorEmailDebugCode("");
    setTwoFactorEmailCodeResendAt(0);
  }, []);

  const switchTwoFactorVerificationMethod = React.useCallback((method: SecurityVerificationMethod) => {
    setTwoFactorVerificationMethod(method);
    setTwoFactorCode("");
    setTwoFactorEmailDebugCode("");
  }, []);

  const toggleLoginMode = React.useCallback(() => {
    if (mode === "register") {
      setMode("login");
      return;
    }
    if (mode === "reset-password") {
      setMode("login");
      return;
    }
    if (canShowRegister) {
      setMode("register");
    }
  }, [canShowRegister, mode]);

  return {
    codeSent,
    configReady,
    emailRegistrationEnabled,
    emailVerificationEnabled,
    handleProviderLogin,
    loginProviders,
    mode,
    onLoginSubmit,
    onRegisterSubmit,
    options,
    password,
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium leading-none text-foreground" htmlFor="reset-password">
                      {t("newPassword")}
                    </label>
                    <Input
                      id="reset-password"
                      type="password"
                      autoComplete="new-password"
                      className="h-9 border-input/50"
                      placeholder={t("newPasswordPlaceholder")}
                      value={resetPassword}
                      onChange={(event) => setResetPassword(event.target.value)}
                      minLength={PASSWORD_MIN_LENGTH}
                      required
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium leading-none text-foreground" htmlFor="reset-code">
                      {t("verificationCode")}
                    </label>
                    <div className="flex gap-2">
                      <Input
                        id="reset-code"
                        inputMode="numeric"
                        autoComplete="one-time-code"
                        className="h-9 border-input/50"
                        placeholder={t("verificationCodePlaceholder")}
                        value={resetCode}
                        onChange={(event) => setResetCode(event.target.value)}
                        required
                      />
                      <Button
                        type="button"
                        variant="secondary"
                        className="h-9 min-w-[4.5rem] shrink-0 rounded-md border-0 bg-muted px-3 text-sm font-semibold text-foreground shadow-none hover:bg-muted/80"
                        disabled={sendingCode || resetCodeCooldownSeconds > 0 || !resetEmail.trim()}
                        onClick={() => {
                          void requestPasswordResetCode();
                        }}
                      >
                        {sendingCode ? <SpinnerLabel>{t("sending")}</SpinnerLabel> : resetCodeCooldownSeconds > 0 ? t("resendIn", { seconds: resetCodeCooldownSeconds }) : resetCodeSent ? t("resend") : t("send")}
                      </Button>
                    </div>
                  </div>
                  <Button
                    className="mt-1 h-9 w-full rounded-md bg-foreground text-sm font-semibold text-background shadow-none hover:bg-foreground/90"
                    type="submit"
                    disabled={submitting || resetCode.length !== 6}
                  >
                    {submitting ? <SpinnerLabel>{t("resettingPassword")}</SpinnerLabel> : t("resetPassword")}
                  </Button>
                </form>
                <div className="mt-6 text-center text-sm font-normal leading-5 text-muted-foreground">
                  {t("rememberPassword")}{" "}
                  <button
                    type="button"
                    className="font-semibold text-foreground underline-offset-4 hover:underline focus-visible:underline focus-visible:outline-none"
                    onClick={() => loginPage.setMode("login")}
                  >
                    {t("back")}
                  </button>
                </div>
              </>
            ) : null}

            {mode === "register" && emailRegistrationEnabled ? (
              <form className="mt-7 space-y-4" onSubmit={onRegisterSubmit}>
                <div className="space-y-2">
                  <label className="text-sm font-medium leading-none text-foreground" htmlFor="register-email">
                    {t("email")}
                  </label>
                  <Input
                    id="register-email"
                    type="email"
                    autoComplete="email"
                    className="h-9 border-input/50"
                    placeholder={t("email")}
                    value={registerEmail}
                    onChange={(event) => updateRegisterEmail(event.target.value)}
                    required
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-medium leading-none text-foreground" htmlFor="register-password">
                    {t("password")}
                  </label>
                  <Input
                    id="register-password"
                    type="password"
                    autoComplete="new-password"
                    className="h-9 border-input/50"
                    placeholder={t("newPasswordPlaceholder")}
                    value={registerPassword}
                    onChange={(event) => setRegisterPassword(event.target.value)}
                    minLength={PASSWORD_MIN_LENGTH}
                    required
                  />
                </div>
                {registrationCodeRequired ? (
                  <div className="space-y-2">
                    <label className="text-sm font-medium leading-none text-foreground" htmlFor="registration-code">
                      {t("registrationCode")}
                    </label>
                    <Input
                      id="registration-code"
                      autoComplete="off"
                      className="h-9 border-input/50"
                      placeholder={t("registrationCodePlaceholder")}
                      value={registrationCode}
                      onChange={(event) => setRegistrationCode(event.target.value.toUpperCase())}
                      required
                    />
                  </div>
                ) : null}
                {registerTurnstileRequired ? (
                  <TurnstileWidget
                    siteKey={registerTurnstileSiteKey}
                    resetSignal={registerTurnstileResetSignal}
                    onTokenChange={setRegisterTurnstileToken}
                  />
                ) : null}
                {emailVerificationEnabled ? (
                  <div className="space-y-2">
                    <label className="text-sm font-medium leading-none text-foreground" htmlFor="register-code">
                      {t("verificationCode")}
                    </label>
                    <div className="flex gap-2">
                      <Input
                        id="register-code"
                        inputMode="numeric"
                        autoComplete="one-time-code"
                        className="h-9 border-input/50"
                        placeholder={t("verificationCodePlaceholder")}
                        value={registerCode}
                        onChange={(event) => setRegisterCode(event.target.value)}
                        required
                      />
                      <Button
                        type="button"
                        variant="secondary"
                        className="h-9 min-w-[4.5rem] shrink-0 rounded-md border-0 bg-muted px-3 text-sm font-semibold text-foreground shadow-none hover:bg-muted/80"
                        disabled={sendingCode || registerCodeCooldownSeconds > 0 || !registerEmail.trim() || (registerTurnstileRequired && !registerTurnstileToken)}
                        onClick={() => {
                          void requestRegisterCode();
                        }}
                      >
                        {sendingCode ? <SpinnerLabel>{t("sending")}</SpinnerLabel> : registerCodeCooldownSeconds > 0 ? t("resendIn", { seconds: registerCodeCooldownSeconds }) : codeSent ? t("resend") : t("send")}
                      </Button>
                    </div>
                  </div>
                ) : null}
                {registerDebugCode ? <p className="text-xs font-medium text-muted-foreground">{t("debugCode", { code: registerDebugCode })}</p> : null}
                <Button
                  className="mt-1 h-9 w-full rounded-md bg-foreground text-sm font-semibold text-background shadow-none hover:bg-foreground/90"
                  type="submit"
                  disabled={submitting || (emailVerificationEnabled && registerCode.length !== 6) || (registerTurnstileRequired && !registerTurnstileToken)}
                >
                  {submitting ? <SpinnerLabel>{t("registering")}</SpinnerLabel> : t("register")}
                </Button>
              </form>
            ) : null}

            {mode === "login" && !twoFactorChallengeToken && loginProviders.length > 0 ? (
              <div className={cn("space-y-2.5", passwordLoginEnabled ? "mt-5" : "mt-7")}>
                {registrationCodeRequired ? (
                  <div className="mb-3 space-y-2">
                    <label className="text-sm font-medium leading-none text-foreground" htmlFor="provider-registration-code">
                      {t("registrationCode")}
                    </label>
                    <Input
                      id="provider-registration-code"
                      autoComplete="off"
                      className="h-9 border-input/50"
                      placeholder={t("registrationCodePlaceholder")}
                      value={registrationCode}
                      onChange={(event) => setRegistrationCode(event.target.value.toUpperCase())}
                    />
                  </div>
                ) : null}
                {loginProviders.map((provider) => (
                  <Button
                    key={provider.publicID}
                    type="button"
                    variant="secondary"
                    className="h-9 w-full rounded-md border-0 bg-muted text-sm font-semibold text-foreground shadow-none hover:bg-muted/80"
                    onClick={() => {
                      void handleProviderLogin(provider.slug);
                    }}
                  >
                    <span className="inline-flex min-w-0 items-center justify-center gap-2">
                      <IdentityProviderIcon
                        name={provider.name}
                        slug={provider.slug}
                        logoURL={provider.logoURL}
                        className="size-5"
                        iconClassName="size-5"
                        fallbackClassName="text-sm font-semibold uppercase text-foreground"
                      />
                      <span className="truncate">{t("providerLogin", { provider: provider.name })}</span>
                    </span>
                  </Button>
                ))}
              </div>
            ) : null}

            {canShowRegisterSwitch && mode !== "reset-password" ? (
              <div className="mt-6 text-center text-sm font-normal leading-5 text-muted-foreground">
                {mode === "register" ? t("alreadyHaveAccount") : t("noAccount")}{" "}
                <button
                  type="button"
                  className="font-semibold text-foreground underline-offset-4 hover:underline focus-visible:underline focus-visible:outline-none"
                  onClick={toggleLoginMode}
                >
                  {mode === "register" ? t("signIn") : t("register")}
                </button>
              </div>
            ) : null}
            </div>
          ) : null}
        </div>

      </div>

      <CustomBrandAttribution className="fixed bottom-4 right-4" />
    </main>
  );
}

"use client";

import * as React from "react";
import { useRouter } from "next/navigation";
import { useTranslations } from "next-intl";
import { Link2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { SpinnerLabel } from "@/components/ui/spinner";
import {
  providerAuthBridgeStorageKey,
  providerPKCEStorageKey,
  TWO_FACTOR_CHALLENGE_STORAGE_KEY,
  TWO_FACTOR_METHODS_STORAGE_KEY,
} from "@/features/auth/model/login-page";
import { useLocalizedErrorMessage } from "@/i18n/use-localized-error";
import { completeProviderBind, completeProviderLogin, exchangeProviderAuthBridgeGrant } from "@/shared/api/auth";
import { ApiError } from "@/shared/api/http-client";
import { DEFAULT_AUTH_NEXT_PATH, normalizeAuthNextPath } from "@/shared/auth/local-path";
import { AppLogo } from "@/shared/components/app-logo";
import { resolveAccessToken } from "@/shared/auth/resolve-access-token";
import { writeSessionSnapshot } from "@/shared/auth/session";

const PROVIDER_EMAIL_CONFLICT_ERROR_CODE = "auth.provider_email_conflict";
const PROVIDER_EMAIL_CONFLICT_ACTION_SIGN_IN_THEN_BIND = "sign_in_then_bind";
const ACCOUNT_SETTINGS_PATH = "/setting/account";

type ProviderEmailConflictDetails = {
  action?: string;
  providerSlug?: string;
  email?: string;
};

type EmailConflictState = {
  providerSlug?: string;
  email?: string;
};

export function AuthCallbackPage() {
  const t = useTranslations("login.oauthCallback");
  const resolveErrorMessage = useLocalizedErrorMessage();
  const router = useRouter();
  const [error, setError] = React.useState("");
  const [emailConflict, setEmailConflict] = React.useState<EmailConflictState | null>(null);
  const handledRef = React.useRef(false);

  const redirectToLogin = React.useCallback(() => {
    router.replace("/login");
  }, [router]);

  const redirectToLoginWithAccountSettingsNext = React.useCallback(() => {
    router.replace(`/login?next=${encodeURIComponent(ACCOUNT_SETTINGS_PATH)}`);
  }, [router]);

  React.useEffect(() => {
    if (handledRef.current) {
      return;
    }
    handledRef.current = true;

    const params = new URLSearchParams(window.location.search);
    const errorMessage = params.get("error");
    if (errorMessage) {
      setError(t("providerError", { error: errorMessage }));
      return;
    }

    const provider = params.get("provider") ?? "";
    const grant = params.get("grant") ?? "";
    if (provider && grant) {
      const stored = readProviderAuthBridgeRequest(provider);
      window.sessionStorage.removeItem(providerAuthBridgeStorageKey(provider));
      if (!stored || !constantTimeStringEqual(params.get("state") ?? "", stored.state)) {
        setError(t("expiredSession"));
        return;
      }
      void exchangeProviderAuthBridgeGrant(provider, {
        clientID: "deeix-web",
        grant,
        codeVerifier: stored.verifier,
      })
        .then((result) => {
          if (result.twoFactorRequired) {
            window.sessionStorage.setItem(TWO_FACTOR_CHALLENGE_STORAGE_KEY, result.twoFactorChallengeToken ?? "");
            window.sessionStorage.setItem(TWO_FACTOR_METHODS_STORAGE_KEY, JSON.stringify(result.verificationMethods ?? ["two_factor"]));
            router.replace(`/login?next=${encodeURIComponent(stored.next)}`);
            return;
          }
          writeSessionSnapshot({ accessToken: result.accessToken, sessionID: result.sessionID });
          router.replace(stored.next);
        })
        .catch((caught) => {
          if (isProviderEmailConflictError(caught)) {
            const details = caught.details as ProviderEmailConflictDetails | undefined;
            setEmailConflict({
              providerSlug: details?.providerSlug?.trim() || undefined,
              email: details?.email?.trim() || undefined,
            });
            return;
          }
          setError(resolveErrorMessage(caught, t("loginFailed")));
        });
      return;
    }
    const code = params.get("code") ?? "";
    const state = params.get("state") ?? "";
    const parsedState = parseProviderState(state);
    const intent = parsedState.intent;
    const nextPath = parsedState.next;
    if (!provider || !code || !state) {
      setError(t("missingParams"));
      return;
    }
    const codeVerifier = window.sessionStorage.getItem(providerPKCEStorageKey(provider)) ?? "";
    window.sessionStorage.removeItem(providerPKCEStorageKey(provider));
    if (!codeVerifier) {
      setError(t("expiredSession"));
      return;
    }

    const redirectURI = `${window.location.origin}${window.location.pathname}?provider=${encodeURIComponent(provider)}`;
    if (intent === "bind") {
      void resolveAccessToken()
        .then((accessToken) => {
          if (!accessToken) {
            throw new Error(t("bindSessionExpired"));
          }
          return completeProviderBind(accessToken, provider, code, state, redirectURI, codeVerifier);
        })
        .then(() => {
          router.replace(nextPath);
        })
        .catch((caught) => {
          setError(resolveErrorMessage(caught, t("bindFailed")));
        });
      return;
    }

    void completeProviderLogin(provider, code, state, redirectURI, codeVerifier, intent)
      .then((result) => {
        if (result.twoFactorRequired) {
          window.sessionStorage.setItem(TWO_FACTOR_CHALLENGE_STORAGE_KEY, result.twoFactorChallengeToken ?? "");
          window.sessionStorage.setItem(TWO_FACTOR_METHODS_STORAGE_KEY, JSON.stringify(result.verificationMethods ?? ["two_factor"]));
          router.replace(`/login?next=${encodeURIComponent(nextPath)}`);
          return;
        }
        writeSessionSnapshot({
          accessToken: result.accessToken,
          sessionID: result.sessionID,
        });
        router.replace(nextPath);
      })
      .catch((caught) => {
        if (isProviderEmailConflictError(caught)) {
          const details = caught.details as ProviderEmailConflictDetails | undefined;
          setEmailConflict({
            providerSlug: details?.providerSlug?.trim() || undefined,
            email: details?.email?.trim() || undefined,
          });
          return;
        }
        setError(resolveErrorMessage(caught, t("loginFailed")));
      });
  }, [resolveErrorMessage, router, t]);

  const conflictProviderLabel = React.useMemo(() => {
    if (!emailConflict?.providerSlug) {
      return t("emailConflict.providerUnknown");
    }
    return emailConflict.providerSlug;
  }, [emailConflict?.providerSlug, t]);

  return (
    <main className="flex min-h-screen items-center justify-center px-4 py-8 text-foreground">
      <div className="w-full max-w-[360px]">
        <div className="flex flex-col items-center text-center">
          <AppLogo width={32} height={32} priority className="h-9 w-auto" />
        </div>

        {error ? (
          <div className="mt-7 space-y-5 text-center">
            <div className="space-y-2">
              <h1 className="text-xl font-semibold leading-7">{t("errorTitle")}</h1>
              <p className="break-words text-sm leading-6 text-muted-foreground">{error}</p>
            </div>
            <Button type="button" className="h-9 w-full rounded-md bg-foreground text-sm font-semibold text-background shadow-none hover:bg-foreground/90" onClick={redirectToLogin}>
              {t("backToLogin")}
            </Button>
          </div>
        ) : emailConflict ? (
          <div className="mt-7 space-y-5">
            <div className="space-y-2 text-center">
              <div className="space-y-2">
                <h1 className="text-xl font-semibold leading-7">{t("emailConflict.title")}</h1>
                <p className="text-sm leading-6 text-muted-foreground">{t("emailConflict.description")}</p>
              </div>
            </div>

            <div className="space-y-2 rounded-md bg-muted/60 px-3 py-3 text-sm">
              <div className="flex min-w-0 items-center justify-between gap-3">
                <span className="shrink-0 text-muted-foreground">{t("emailConflict.providerLabel")}</span>
                <span className="min-w-0 truncate text-right font-medium text-foreground">{conflictProviderLabel}</span>
              </div>
              {emailConflict.email ? (
                <div className="flex min-w-0 items-center justify-between gap-3">
                  <span className="shrink-0 text-muted-foreground">{t("emailConflict.emailLabel")}</span>
                  <span className="min-w-0 truncate text-right font-medium text-foreground">{emailConflict.email}</span>
                </div>
              ) : null}
            </div>

            <div className="space-y-3">
              <Button type="button" className="h-9 w-full rounded-md bg-foreground text-sm font-semibold text-background shadow-none hover:bg-foreground/90" onClick={redirectToLoginWithAccountSettingsNext}>
                <Link2 className="size-4" aria-hidden="true" />
                {t("emailConflict.signInExistingAccount")}
              </Button>
            </div>

            <p className="text-center text-xs leading-5 text-muted-foreground">
              {t("emailConflict.notePrefix")}
              <button
                type="button"
                className="font-medium text-foreground underline-offset-4 hover:underline focus-visible:underline focus-visible:outline-none"
                onClick={redirectToLogin}
              >
                {t("emailConflict.noteLink")}
              </button>
              {t("emailConflict.noteSuffix")}
            </p>
          </div>
        ) : (
          <div className="mt-7 flex flex-col items-center gap-3 text-center text-sm text-muted-foreground">
            <SpinnerLabel>{t("loading")}</SpinnerLabel>
            <p>{t("loadingDescription")}</p>
          </div>
        )}
      </div>
    </main>
  );
}

function readProviderAuthBridgeRequest(slug: string): { verifier: string; state: string; intent: "login" | "register"; next: string } | null {
  try {
    const raw = window.sessionStorage.getItem(providerAuthBridgeStorageKey(slug));
    if (!raw) return null;
    const parsed = JSON.parse(raw) as { verifier?: string; state?: string; intent?: string; next?: string };
    if (!parsed.verifier || !parsed.state) return null;
    return {
      verifier: parsed.verifier,
      state: parsed.state,
      intent: parsed.intent === "register" ? "register" : "login",
      next: normalizeAuthNextPath(parsed.next),
    };
  } catch {
    return null;
  }
}

function constantTimeStringEqual(left: string, right: string): boolean {
  if (left.length !== right.length) return false;
  let difference = 0;
  for (let index = 0; index < left.length; index += 1) {
    difference |= left.charCodeAt(index) ^ right.charCodeAt(index);
  }
  return difference === 0;
}

function isProviderEmailConflictError(error: unknown): boolean {
  if (!(error instanceof ApiError) || error.errorCode !== PROVIDER_EMAIL_CONFLICT_ERROR_CODE) {
    return false;
  }
  const details = error.details as ProviderEmailConflictDetails | undefined;
  return details?.action === PROVIDER_EMAIL_CONFLICT_ACTION_SIGN_IN_THEN_BIND;
}

function parseProviderState(raw: string): { next: string; intent: "login" | "register" | "bind" } {
  try {
    const [encodedPayload] = raw.split(".");
    if (!encodedPayload) return { next: DEFAULT_AUTH_NEXT_PATH, intent: "login" };
    const padded = encodedPayload.replaceAll("-", "+").replaceAll("_", "/").padEnd(Math.ceil(encodedPayload.length / 4) * 4, "=");
    const parsed = JSON.parse(atob(padded)) as { next?: string; intent?: string };
    const intent = parsed.intent ?? "";
    return {
      next: normalizeAuthNextPath(parsed.next),
      intent: intent === "register" ? "register" : intent === "bind" ? "bind" : "login",
    };
  } catch {
    return { next: DEFAULT_AUTH_NEXT_PATH, intent: "login" };
  }
}
  return data.user;
}

