	payload, err := json.Marshal(state)
	if err != nil {
		return "", err
	}
	encodedPayload := base64.RawURLEncoding.EncodeToString(payload)
	signature := providerStateSignature(s.cfg.Snapshot().JWTSecret, encodedPayload)
	return encodedPayload + "." + signature, nil
}

