	Intent        string
	Next          string
	RegistrationCode string
}

type ProviderAuthBridgeStartResult struct {
	AuthorizationURL string
	ExpiresAt        time.Time
}

type ProviderAuthBridgeCallbackInput struct {
	Code          string
