  "chat-files": "sections.chatFiles",
  about: "sections.about",
};

function resolveActiveSectionFromPath(pathname: string, basePath: string): AdminSection {
  const normalizedBasePath = basePath.replace(/\/$/, "");
  const section = ADMIN_SECTIONS.find((item) => {
    const href = `${normalizedBasePath}${item.href}`;
    return pathname === href || pathname.startsWith(`${href}/`);
  });

  return section?.id ?? "statistics";
}

export function AdminSidebar({
  basePath,
}: {
  basePath: string;
}) {
  const t = useTranslations("adminUsers");
  const tAbout = useTranslations("adminUsers.aboutPage");
  const pathname = usePathname();
  const activeSection = resolveActiveSectionFromPath(pathname, basePath);
  const activeLinkRef = React.useRef<HTMLAnchorElement | null>(null);
  const cachedLatestRelease = React.useSyncExternalStore(
    subscribeLatestReleaseChange,
    getCachedLatestReleaseSnapshot,
    getServerLatestReleaseSnapshot,
  );
  const updateRelease = resolveAvailableRelease(packageMeta.version, cachedLatestRelease);
  const sectionLabel = React.useCallback(
    (id: AdminSection, fallback: string) => {
      return t(ADMIN_SECTION_LABEL_KEYS[id]) || fallback;
    },
    [t],
  );

  React.useEffect(() => {
    activeLinkRef.current?.scrollIntoView({
      block: "nearest",
      inline: "center",
    });
  }, [activeSection]);

  return (
    <aside className="w-full shrink-0 xl:max-w-64">
      <div className="space-y-3 xl:sticky xl:top-6 xl:space-y-5">
        <div className="flex h-9 items-center px-1 xl:h-10">
          <h1 className="text-xl font-semibold tracking-normal xl:text-2xl">{t("adminTitle")}</h1>
        </div>

        <nav
          aria-label={t("adminTitle")}
          className="flex gap-1.5 overflow-x-auto overscroll-x-contain pb-1 [scrollbar-width:none] [-ms-overflow-style:none] xl:grid xl:gap-1 xl:overflow-visible xl:pb-0 [&::-webkit-scrollbar]:hidden"
        >
          {ADMIN_SECTIONS.map((item) => {
            const active = item.id === activeSection;

            return (
              <Link
                key={item.id}
                ref={active ? activeLinkRef : undefined}
                href={`${basePath}${item.href}`}
                prefetch={false}
                aria-current={active ? "page" : undefined}
                className={cn(
                  "relative flex h-8 shrink-0 scroll-mx-3 items-center justify-between gap-2 whitespace-nowrap rounded-md px-3 text-sm font-medium transition-colors xl:h-9 xl:w-full xl:px-3.5",
                  active
                    ? "bg-sidebar-accent text-sidebar-accent-foreground"
                    : "text-sidebar-foreground hover:bg-sidebar-accent hover:text-sidebar-accent-foreground",
                )}
              >
                <span className="truncate">{sectionLabel(item.id, item.label)}</span>
                {item.id === "about" && updateRelease ? (
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="ml-auto inline-flex size-4 shrink-0 items-center justify-center text-rose-500">
                        <CircleArrowUp className="size-3.5" aria-label={tAbout("updateAvailableIndicator")} />
                      </span>
                    </TooltipTrigger>
                    <TooltipContent>
                      <AdminUpdateTooltipContent updateRelease={updateRelease} />
                    </TooltipContent>
                  </Tooltip>
                ) : null}
              </Link>
            );
          })}
        </nav>
      </div>
    </aside>
  );
}

export async function writeClipboardText(value: string): Promise<void> {
  let clipboardError: unknown;

  if (typeof navigator !== "undefined" && navigator.clipboard?.writeText) {
    try {
      await navigator.clipboard.writeText(value);
      return;
    } catch (error) {
      clipboardError = error;
    }
  }

  if (typeof document === "undefined" || !document.body) {
    throw clipboardError ?? new Error("Clipboard is unavailable");
  }

  const textarea = document.createElement("textarea");
  textarea.value = value;
  textarea.setAttribute("readonly", "");
  textarea.style.position = "fixed";
  textarea.style.left = "-9999px";
  textarea.style.top = "0";
  textarea.style.opacity = "0";

  const activeElement = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const selection = document.getSelection();
  const selectedRange = selection?.rangeCount ? selection.getRangeAt(0) : null;

  document.body.appendChild(textarea);
  textarea.focus({ preventScroll: true });
  textarea.select();
  textarea.setSelectionRange(0, value.length);

  try {
    const copied = document.execCommand("copy");
    if (!copied) {
      throw clipboardError ?? new Error("Copy command failed");
    }
  } finally {
    textarea.remove();
    try {
      if (selectedRange && selection) {
        selection.removeAllRanges();
        selection.addRange(selectedRange);
      }
      activeElement?.focus({ preventScroll: true });
    } catch {
      // Restoring focus or selection must not turn a successful copy into a failed one.
    }
  }
}
"use client";

import * as React from "react";
import { Check, Copy } from "lucide-react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { writeClipboardText } from "@/shared/lib/clipboard";

export type CopyActionMessages = {
  copied: string;
  copiedDescription?: string;
  failed: string;
  failedDescription?: string;
  empty?: string;
  emptyDescription?: string;
};

type CopyActionOptions = {
  messages: CopyActionMessages;
  resetDelayMs?: number;
};

export type CopyActionInput = {
  key?: string;
  copied?: string;
  copiedDescription?: string;
  failed?: string;
  failedDescription?: string;
  empty?: string;
  emptyDescription?: string;
};

export function useCopyAction({ messages, resetDelayMs = 1500 }: CopyActionOptions) {
  const [copied, setCopied] = React.useState(false);
  const [copiedKey, setCopiedKey] = React.useState<string | null>(null);
  const [pending, setPending] = React.useState(false);
  const resetTimerRef = React.useRef<number | null>(null);

  const clearResetTimer = React.useCallback(() => {
    if (resetTimerRef.current) {
      window.clearTimeout(resetTimerRef.current);
      resetTimerRef.current = null;
    }
  }, []);

  const reset = React.useCallback(() => {
    clearResetTimer();
    setCopied(false);
    setCopiedKey(null);
  }, [clearResetTimer]);

  React.useEffect(() => reset, [reset]);

  const copy = React.useCallback(
    async (value: string, overrides: CopyActionInput = {}): Promise<boolean> => {
      const text = value.trim() ? value : "";
      if (!text) {
        setCopied(false);
        setCopiedKey(null);
        const emptyMessage = overrides.empty ?? messages.empty;
        if (emptyMessage) {
          toast.error(emptyMessage, { description: overrides.emptyDescription ?? messages.emptyDescription });
        }
        return false;
      }

      setPending(true);
      clearResetTimer();
      try {
        await writeClipboardText(text);
        setCopied(true);
        setCopiedKey(overrides.key ?? null);
        toast.success(overrides.copied ?? messages.copied, {
          description: overrides.copiedDescription ?? messages.copiedDescription,
        });
        resetTimerRef.current = window.setTimeout(() => {
          setCopied(false);
          setCopiedKey(null);
          resetTimerRef.current = null;
        }, resetDelayMs);
        return true;
      } catch {
        setCopied(false);
        setCopiedKey(null);
        toast.error(overrides.failed ?? messages.failed, {
          description: overrides.failedDescription ?? messages.failedDescription,
        });
        return false;
      } finally {
        setPending(false);
      }
    },
    [clearResetTimer, messages, resetDelayMs],
  );

  const isCopied = React.useCallback((key?: string) => {
    if (key === undefined) {
      return copied;
    }
    return copied && copiedKey === key;
  }, [copied, copiedKey]);

  return {
    copied,
    copy,
    isCopied,
    pending,
    reset,
  };
}

type CopyActionButtonProps = Omit<React.ComponentProps<typeof Button>, "onClick"> & {
  value?: string;
  resolveValue?: () => string | Promise<string>;
  messages: CopyActionMessages;
  copyOptions?: CopyActionInput;
  resetDelayMs?: number;
  iconClassName?: string;
  copyIcon?: React.ReactNode;
  copiedIcon?: React.ReactNode;
  onCopied?: () => void;
  onResolveError?: (error: unknown) => void;
};

export function CopyActionButton({
  value,
  resolveValue,
  messages,
  copyOptions,
  resetDelayMs,
  iconClassName = "size-3.5",
  copyIcon,
  copiedIcon,
  children,
  disabled,
  onCopied,
  onResolveError,
  ...buttonProps
}: CopyActionButtonProps) {
  const { copied, copy, pending } = useCopyAction({ messages, resetDelayMs });
  const [resolving, setResolving] = React.useState(false);

  const handleClick = React.useCallback(async () => {
    setResolving(true);
    try {
      const resolvedValue = resolveValue ? await resolveValue() : (value ?? "");
      const ok = await copy(resolvedValue, copyOptions);
      if (ok) {
        onCopied?.();
      }
    } catch (error) {
      if (onResolveError) {
        onResolveError(error);
      } else {
        toast.error(messages.failed, { description: messages.failedDescription });
      }
    } finally {
      setResolving(false);
    }
  }, [copy, copyOptions, messages, onCopied, onResolveError, resolveValue, value]);

  return (
    <Button
      {...buttonProps}
      disabled={disabled || pending || resolving}
      onClick={() => void handleClick()}
    >
      {copied ? (copiedIcon ?? <Check className={iconClassName} />) : (copyIcon ?? <Copy className={iconClassName} />)}
      {children}
    </Button>
  );
}
