type RequestBodyErrorDetails struct {
	Reason      string                  `json:"reason"`
	Offset      int64                   `json:"offset,omitempty"`
	Field       string                  `json:"field,omitempty"`
	Expected    string                  `json:"expected,omitempty"`
	Value       string                  `json:"value,omitempty"`
