	if errors.As(err, &typeErr) {
		field := requestFieldName(typeErr.Field)
		return fmt.Sprintf("%s has invalid type", field), RequestBodyErrorDetails{
			Reason:   "json_type",
			Field:    field,
			Expected: typeErr.Type.String(),
			Value:    typeErr.Value,
