package wechat

import (
	"context"
	"errors"

	domainregistrationcode "github.com/DEEIX-AI/DEEIX-Chat/backend/internal/domain/registrationcode"
	"github.com/DEEIX-AI/DEEIX-Chat/backend/internal/infra/persistence/dberror"
	"github.com/DEEIX-AI/DEEIX-Chat/backend/internal/infra/persistence/models"
	"github.com/DEEIX-AI/DEEIX-Chat/backend/internal/repository"
	"gorm.io/gorm"
)

type Repo struct{ db *gorm.DB }

func NewRepo(db *gorm.DB) *Repo { return &Repo{db: db} }

// IssueRegistrationCode is idempotent for an OpenID and atomic for first issuance.
func (r *Repo) IssueRegistrationCode(ctx context.Context, openID, code string) (string, error) {
	var issued string
	err := r.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		var existing models.WeChatRegistrationIssuance
		if err := tx.Where("open_id = ?", openID).First(&existing).Error; err == nil {
			var registration models.RegistrationCode
			if err := tx.First(&registration, existing.RegistrationCodeID).Error; err != nil {
				return err
			}
			issued = registration.Code
			return nil
		} else if !errors.Is(err, gorm.ErrRecordNotFound) {
			return err
		}

		registration := models.RegistrationCode{
			Code:   code,
			CodeHint: code[len(code)-4:],
			Status: domainregistrationcode.StatusActive,
		}
		if err := tx.Create(&registration).Error; err != nil {
			if dberror.IsUniqueConstraint(err) {
				return repository.ErrDuplicate
			}
			return err
		}
		issuance := models.WeChatRegistrationIssuance{OpenID: openID, RegistrationCodeID: registration.ID}
		if err := tx.Create(&issuance).Error; err != nil {
			if dberror.IsUniqueConstraint(err) {
				return repository.ErrDuplicate
			}
			return err
		}
		issued = registration.Code
		return nil
	})
	return issued, err
}

var _ repository.WeChatRegistrationRepository = (*Repo)(nil)
package wechat

import (
	"context"
	"crypto/rand"
	"fmt"
	"strings"

	"github.com/DEEIX-AI/DEEIX-Chat/backend/internal/repository"
)

const keyword = "13003"

type Service struct{ repo repository.WeChatRegistrationRepository }

func NewService(repo repository.WeChatRegistrationRepository) *Service { return &Service{repo: repo} }

func (s *Service) IssueRegistrationCode(ctx context.Context, openID string) (string, error) {
	openID = strings.TrimSpace(openID)
	if openID == "" {
		return "", repository.ErrInvalidInput
	}
	for attempt := 0; attempt < 5; attempt++ {
		code, err := generateCode()
		if err != nil {
			return "", err
		}
		issued, err := s.repo.IssueRegistrationCode(ctx, openID, code)
		if err == repository.ErrDuplicate {
			continue
		}
		return issued, err
	}
	return "", repository.ErrDuplicate
}

func IsRegistrationKeyword(content string) bool { return strings.TrimSpace(content) == keyword }

func generateCode() (string, error) {
	const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
	raw := make([]byte, 16)
	if _, err := rand.Read(raw); err != nil {
		return "", err
	}
	buf := make([]byte, len(raw))
	for i := range raw {
		buf[i] = alphabet[int(raw[i])%len(alphabet)]
	}
	return fmt.Sprintf("%s-%s-%s-%s", string(buf[:4]), string(buf[4:8]), string(buf[8:12]), string(buf[12:])), nil
}
