--- backend/internal/shared/buildinfo/buildinfo.go
package buildinfo

import (
	"os"
	"strings"
	"sync"
)

// Version is injected from the repository-level VERSION file at build time.
var Version = "dev"

// Commit is injected from the current git commit at build time.
var Commit = "unknown"

// BuildTime is injected as an RFC3339 UTC timestamp at build time.
var BuildTime = "unknown"

var (
	versionOnce  sync.Once
	versionValue string
)

type Info struct {
	Product   string `json:"product"`
	Version   string `json:"version"`
	Commit    string `json:"commit"`
	BuildTime string `json:"buildTime"`
	BuildID   string `json:"buildID"`
}

func Snapshot() Info {
	return Info{
		Product:   "DEEIX Chat",
		Version:   ResolveVersion(),
		Commit:    Commit,
		BuildTime: BuildTime,
		BuildID:   ResolveBuildID(),
	}
}

func ResolveBuildID() string {
	parts := []string{ResolveVersion()}
	for _, value := range []string{Commit, BuildTime} {
		normalized := strings.TrimSpace(value)
		if normalized == "" || normalized == "unknown" || normalized == "dev" {
			continue
		}
		parts = append(parts, normalized)
	}
	return strings.Join(parts, "-")
}

func ResolveVersion() string {
	versionOnce.Do(func() {
		if normalized := strings.TrimSpace(Version); normalized != "" && normalized != "dev" {
			versionValue = normalized
			return
		}
		for _, path := range []string{"VERSION", "../VERSION", "../../VERSION"} {
			content, err := os.ReadFile(path)
			if err != nil {
				continue
			}
			if normalized := strings.TrimSpace(string(content)); normalized != "" {
				versionValue = normalized
				return
			}
		}
		versionValue = strings.TrimSpace(Version)
		if versionValue == "" {
			versionValue = "dev"
		}
	})
	return versionValue
}
--- .github/workflows/ghcr-image.yml
name: GHCR Image

on:
  push:
    branches:
      - main
      - dev
    tags:
      - "v*.*.*"
  pull_request:
    branches:
      - main
      - dev
  workflow_dispatch:

permissions:
  contents: read
  packages: write

jobs:
  build_ghcr_image:
    name: Build image (${{ matrix.arch }})
    strategy:
      fail-fast: false
      matrix:
        include:
          - arch: amd64
            platform: linux/amd64
            runner: ubuntu-24.04
          - arch: arm64
            platform: linux/arm64
            runner: ubuntu-24.04-arm
    runs-on: ${{ matrix.runner }}

    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Set up Buildx
        uses: docker/setup-buildx-action@v3

      - name: Normalize image name
        id: image
        shell: bash
        run: |
          image_name=$(printf '%s' "$GITHUB_REPOSITORY" | tr '[:upper:]' '[:lower:]')
          echo "name=ghcr.io/$image_name" >> "$GITHUB_OUTPUT"

      - name: Docker metadata
        id: meta
        uses: docker/metadata-action@v5
        with:
          images: ${{ steps.image.outputs.name }}
          tags: |
            type=ref,event=branch,suffix=-${{ matrix.arch }}
            type=ref,event=tag,suffix=-${{ matrix.arch }}
            type=raw,value=latest-${{ matrix.arch }},enable=${{ github.ref == 'refs/heads/main' }}

      - name: Login to GHCR
        if: github.event_name != 'pull_request'
        uses: docker/login-action@v4
        with:
          registry: ghcr.io
          username: ${{ github.actor }}
          password: ${{ secrets.GITHUB_TOKEN }}

      - name: Build and publish
        uses: docker/build-push-action@v6
        with:
          context: .
          file: ./Dockerfile
          platforms: ${{ matrix.platform }}
          push: ${{ github.event_name != 'pull_request' }}
          tags: ${{ steps.meta.outputs.tags }}
          labels: ${{ steps.meta.outputs.labels }}
          build-args: |
            GIT_COMMIT=${{ github.sha }}
          cache-from: type=gha,scope=${{ matrix.arch }}
          cache-to: type=gha,scope=${{ matrix.arch }},mode=max

  merge:
    name: Merge image
    runs-on: ubuntu-latest
    needs:
      - build_ghcr_image
    if: github.event_name != 'pull_request'

    steps:
      - name: Set up Buildx
        uses: docker/setup-buildx-action@v3

      - name: Normalize image name
        id: image
        shell: bash
        run: |
          image_name=$(printf '%s' "$GITHUB_REPOSITORY" | tr '[:upper:]' '[:lower:]')
          echo "name=ghcr.io/$image_name" >> "$GITHUB_OUTPUT"

      - name: Docker metadata
        id: meta
        uses: docker/metadata-action@v5
        with:
          images: ${{ steps.image.outputs.name }}
          tags: |
            type=ref,event=branch
            type=ref,event=tag
            type=raw,value=latest,enable=${{ github.ref == 'refs/heads/main' }}

      - name: Login to GHCR
        uses: docker/login-action@v4
        with:
          registry: ghcr.io
          username: ${{ github.actor }}
          password: ${{ secrets.GITHUB_TOKEN }}

      - name: Create manifest list
        run: |
          jq -cr '.tags[]' <<< "$DOCKER_METADATA_OUTPUT_JSON" | while read -r tag; do
            docker buildx imagetools create \
              -t "$tag" \
              "${tag}-amd64" \
              "${tag}-arm64"
          done

      - name: Inspect image
        run: docker buildx imagetools inspect "${{ steps.image.outputs.name }}:${{ steps.meta.outputs.version }}"
