// SeedModelVendors 鍒濆鍖栧唴缃巶鍟嗭紝骞朵负瀛橀噺妯″瀷涓殑鎶€鏈巶鍟嗚ˉ榻愮洰褰曢」銆?// 鍚?key 鐨勭幇鏈夌洰褰曢」浼氭檵鍗囦负鍐呯疆锛屼絾绠＄悊鍛樹慨鏀圭殑灞曠ず鍚嶇О銆佸浘鏍囧拰鎺掑簭涓嶄細琚鐩栥€?func SeedModelVendors(db *gorm.DB) error {
	return db.Transaction(func(tx *gorm.DB) error {
		for _, item := range domainchannel.BuiltInModelVendors() {
			entity := model.LLMModelVendor{
